INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:analysis','analysis','n','تحلیل، تجزیه و تحلیل','/əˈnælɪsɪs/ · a careful examination','a detailed analysis of the week''s news','[["a detailed analysis of the week''s news","تحلیل دقیق اخبار هفته"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:approach','approach','v','نزدیک شدن؛ رویکرد، روش','/əˈproʊtʃ/ · v., n. · move nearer; method','He approached the issue from a historical perspective.','[["He approached the issue from a historical perspective.","او از منظر تاریخی به موضوع پرداخت."],["We need a new approach to the problem.","ما به یک رویکرد جدید برای مشکل نیاز داریم."],["Her approach to teaching is very creative.","رویکرد او به تدریس بسیار خلاقانه است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:area','area','n','منطقه، ناحیه؛ حوزه','/ˈeriə/ · region, zone','Crime rates are much higher in urban areas.','[["Crime rates are much higher in urban areas.","نرخ جرم و جنایت در مناطق شهری بسیار بالاتر است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:assess','assess','v','ارزیابی کردن، سنجیدن','/əˈses/ · evaluate; judge','a report to assess the impact of advertising on children','[["a report to assess the impact of advertising on children","گزارشی برای ارزیابی تاثیر تبلیغات بر کودکان"],["Teachers assess students regularly.","معلمان به طور منظم دانش آموزان را ارزیابی می‌کنند."],["Teachers assess students'' work every week.","معلمان هر هفته کار دانش آموزان را ارزیابی می‌کنند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:assume','assume','v','فرض کردن، پنداشتن','/əˈsuːm/ · presume','I think we can safely assume that he is out of town.','[["I think we can safely assume that he is out of town.","فکر می‌کنم با خیال راحت می‌توانیم فرض کنیم که او خارج از شهر است."],["I assume you have heard the news.","فکر می‌کنم شما این خبر را شنیده اید."],["I assumed that you already knew.","من حدس زدم که شما قبلا می‌دانستید."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:authority','authority','n','اقتدار، اختیار؛ مقامات، مسئولان','/əˈθɒrəti/ · power; people in charge','The French authorities have refused to issue him a visa.','[["The French authorities have refused to issue him a visa.","مقامات فرانسه از صدور ویزا برای او خودداری کرده اند."],["Local authorities closed the road.","مقامات محلی جاده را بستند."],["Parents need to have authority over young children.","والدین باید بر فرزندان خردسال اقتدار داشته باشند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:available','available','adj','در دسترس، موجود','/əˈveɪləbəl/ · accessible','Tickets are available from the box office.','[["Tickets are available from the box office.","بلیط از گیشه موجود است."],["Is this room available tonight?","آیا این اتاق امشب موجود است؟"],["Is this seat available?","آیا این صندلی موجود است؟"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:benefit','benefit','n','سود، مزیت، فایده','/ˈbenəfɪt/ · advantage','the benefits of a university education','[["the benefits of a university education","مزایای تحصیل دانشگاهی"],["Exercise has many benefits.","ورزش فواید زیادی دارد."],["The new law will be of benefit to everyone.","قانون جدید به نفع همه خواهد بود."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:concept','concept','n','مفهوم، انگاره','/ˈkɒnsept/ · idea','She is familiar with basic concepts of psychology.','[["She is familiar with basic concepts of psychology.","او با مفاهیم اولیه روانشناسی آشناست."],["The concept of time is difficult to explain.","توضیح مفهوم زمان دشوار است."],["Children learn basic mathematical concepts.","کودکان مفاهیم اولیه ریاضی را یاد می‌گیرند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:consistent','consistent','adj','سازگار، ثابت، پیوسته؛ استوار','/kənˈsɪstənt/ · continuous','We need to be consistent in our approach.','[["We need to be consistent in our approach.","ما باید در رویکرد خود ثابت قدم باشیم."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:constitutional','constitutional','adj','قانونی، مطابق قانون اساسی','/ˌkɒnstəˈtjuːʃənəl/ · legal','Whatever procedure we follow, it must be constitutional.','[["Whatever procedure we follow, it must be constitutional.","هر رویه ای که دنبال کنیم باید طبق قانون اساسی باشد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:context','context','n','زمینه، بافت، شرایط','/ˈkɒntekst/ · situation','the political context of the election','[["the political context of the election","زمینه سیاسی انتخابات"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:contract','contract','n','قرارداد','/ˈkɒntrækt/ · a legal written agreement','The contract requires him to finish work by this year.','[["The contract requires him to finish work by this year.","طبق قرارداد او باید تا سال جاری کار را تمام کند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:create','create','v','ایجاد کردن، خلق کردن، ساختن','/kriˈeɪt/ · make, produce','He believes the universe was created by a big explosion.','[["He believes the universe was created by a big explosion.","او معتقد است که جهان بر اثر یک انفجار بزرگ ایجاد شده است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:data','data','n','داده‌ها، اطلاعات','/ˈdeɪtə, ˈdɑːtə/ · information or facts','The analysis was based on data collected in the field.','[["The analysis was based on data collected in the field.","تجزیه و تحلیل بر اساس داده‌های جمع آوری شده در میدان انجام شد."],["The data show a clear pattern.","داده‌ها یک الگوی واضح را نشان می‌دهد."],["The data show a clear increase in temperature.","داده‌ها افزایش واضح دما را نشان می‌دهد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:define','define','v','تعریف کردن، مشخص کردن','/dɪˈfaɪn/ · describe','There are many definitions of the word ''feminism''.','[["There are many definitions of the word ''feminism''.","تعاریف زیادی از کلمه \"فمینیسم\" وجود دارد."],["How do you define success?","موفقیت را چگونه تعریف می‌کنید؟"],["How would you define happiness?","خوشبختی را چگونه تعریف می‌کنید؟"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:derive','derive','v','به دست آوردن، مشتق شدن (از)','/dɪˈraɪv/ · get sth from sth','Dairy products are derived from milk.','[["Dairy products are derived from milk.","لبنیات از شیر گرفته می‌شود."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:distribute','distribute','v','توزیع کردن، پخش کردن','/dɪˈstrɪbjuːt/ · give, pass, hand','She was responsible for product distribution.','[["She was responsible for product distribution.","او مسئول توزیع محصول بود."],["Seeds are distributed by the wind.","دانه‌ها توسط باد توزیع می‌شوند."],["Volunteers distributed food to the families.","داوطلبان بین خانواده‌ها غذا توزیع کردند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:economic','economic','adj','اقتصادی','/ˌekəˈnɒmɪk/ · relating to money','Economic growth is slow.','[["Economic growth is slow.","رشد اقتصادی کند است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:environment','environment','n','محیط، محیط زیست','/ɪnˈvaɪrənmənt/ · surroundings; the natural world','We''re trying to create a better business environment.','[["We''re trying to create a better business environment.","ما در تلاش هستیم تا فضای کسب و کار بهتری ایجاد کنیم."],["We must protect the environment.","ما باید از محیط زیست محافظت کنیم."],["We must protect the environment for future generations.","ما باید از محیط زیست برای نسل‌های آینده محافظت کنیم."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:establish','establish','v','تأسیس کردن، برقرار کردن','/ɪˈstæblɪʃ/ · set up, found','The company was established in 1899.','[["The company was established in 1899.","این شرکت در سال 1899 تاسیس شد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:estimate','estimate','n','تخمین؛ برآورد کردن','/ˈestəmət/ · n., v. · calculate, judge','It is not easy to estimate how many people have the disease.','[["It is not easy to estimate how many people have the disease.","تخمین زدن تعداد افراد مبتلا به این بیماری آسان نیست."],["Scientists estimate that the tree is 2,000 years old.","دانشمندان تخمین می‌زنند که این درخت 2000 سال سن دارد."],["It is estimated that a million people visited the exhibition.","تخمین زده می‌شود که یک میلیون نفر از این نمایشگاه بازدید کرده اند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:evidence','evidence','n','شواهد، مدرک','/ˈevɪdəns/ · proof, document','Evidence shows that global warming is definitely occurring.','[["Evidence shows that global warming is definitely occurring.","شواهد نشان می‌دهد که گرم شدن کره زمین قطعا در حال وقوع است."],["There is no evidence of life on Mars.","هیچ مدرکی از حیات در مریخ وجود ندارد."],["There is no evidence that he stole the money.","هیچ مدرکی دال بر دزدیدن پول وجود ندارد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:export','export','n','صادرات؛ صادر کردن','/ˈekspɔːt/ · n., v. · sell goods to another country · ≠ import','Wheat is one of the country''s chief exports.','[["Wheat is one of the country''s chief exports.","گندم یکی از صادرات عمده این کشور است."],["Iran exports pistachios to many countries.","ایران به بسیاری از کشورها پسته صادر می‌کند."],["The country exports oil and gas.","این کشور نفت و گاز صادر می‌کند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:factor','factor','n','عامل','/ˈfæktər/ · one of several things that influence sth','Obesity is a major risk factor for heart disease.','[["Obesity is a major risk factor for heart disease.","چاقی یک عامل خطر اصلی برای بیماری قلبی است."],["Diet is a key factor in health.","رژیم غذایی یک عامل کلیدی در سلامتی است."],["Price is an important factor when buying a house.","قیمت یک فاکتور مهم هنگام خرید خانه است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:financial','financial','adj','مالی','/fəˈnænʃəl, faɪ-/ · relating to money or its management','financial advisor, financial aid','[["financial advisor, financial aid","مشاور مالی، کمک مالی"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:formula','formula','n','فرمول، دستور','/ˈfɔːrmjələ/ · a set of rules','His investment strategy is based on a simple formula.','[["His investment strategy is based on a simple formula.","استراتژی سرمایه گذاری او بر اساس یک فرمول ساده است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:function','function','n','کارکرد، عملکرد؛ مراسم','/ˈfʌŋkʃən/ · purpose, event','The church fulfils a valuable social function.','[["The church fulfils a valuable social function.","کلیسا یک کارکرد اجتماعی ارزشمند را انجام می‌دهد."],["The function of the heart is to pump blood.","وظیفه قلب پمپاژ خون است."],["This button has several functions.","این دکمه چندین عملکرد دارد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:identify','identify','v','شناسایی کردن، تشخیص دادن','/aɪˈdentɪfaɪ/ · recognize','The corpse was identified on the basis of dental records.','[["The corpse was identified on the basis of dental records.","جسد بر اساس سوابق دندانپزشکی شناسایی شد."],["Can you identify this plant?","آیا می‌توانید این گیاه را شناسایی کنید؟"],["The police identified the man from the photo.","پلیس از روی عکس این مرد را شناسایی کرد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:income','income','n','درآمد','/ˈɪŋkʌm/ · money you earn from working','He earns a good income as a consultant.','[["He earns a good income as a consultant.","او به عنوان مشاور درآمد خوبی کسب می‌کند."],["Average income has increased.","درآمد متوسط ​​افزایش یافته است."],["Families on low incomes need more support.","خانواده‌های کم درآمد نیاز به حمایت بیشتری دارند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:indicate','indicate','v','نشان دادن، حاکی بودن از','/ˈɪndɪkeɪt/ · show, demonstrate','Research indicates that teachers are dissatisfied with their salary.','[["Research indicates that teachers are dissatisfied with their salary.","تحقیقات نشان می‌دهد که معلمان از حقوق خود ناراضی هستند."],["The results indicate a strong link.","نتایج نشان دهنده یک پیوند قوی است."],["Dark clouds indicate that rain is coming.","ابرهای تیره نشان می‌دهد که باران در راه است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:individual','individual','n','فرد؛ فردی، شخصی','/ˌɪndəˈvɪdʒuəl/ · n., adj. · belonging to one person','The competition is open to both teams and individuals.','[["The competition is open to both teams and individuals.","شرکت در این مسابقات به دو صورت تیمی و انفرادی آزاد است."],["Every individual has the right to education.","هر فردی حق تحصیل دارد."],["Every individual has the right to free speech.","هر فردی حق آزادی بیان دارد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:interpret','interpret','v','تفسیر کردن، تعبیر کردن؛ ترجمه کردن','/ɪnˈtɜːprɪt/ · translate, explain','This writer''s work demands interpretation.','[["This writer''s work demands interpretation.","کار این نویسنده تفسیر می‌خواهد."],["How do you interpret this poem?","این شعر را چگونه تفسیر می‌کنید؟"],["She interpreted his silence as agreement.","او سکوت او را به توافق تعبیر کرد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:involve','involve','v','شامل شدن، در بر داشتن؛ درگیر کردن','/ɪnˈvɒlv/ · include','More than 30 software firms were involved in the project.','[["More than 30 software firms were involved in the project.","بیش از 30 شرکت نرم افزاری در این پروژه مشارکت داشتند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:issue','issue','n','موضوع، مسئله؛ صادر کردن','/ˈɪʃuː/ · n., v. · an important topic','Water purity is a public health issue.','[["Water purity is a public health issue.","خلوص آب یک مسئله بهداشت عمومی است."],["Climate change is a global issue.","تغییر اقلیم یک مسئله جهانی است."],["We discussed several issues at the meeting.","در این جلسه درباره چند موضوع بحث کردیم."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:labor','labor','n','کار، نیروی کار؛ زحمت کشیدن','/ˈleɪbər/ · n., v. · work, worker','Many women do hard manual labour.','[["Many women do hard manual labour.","بسیاری از زنان کارهای یدی سخت انجام می‌دهند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:legal','legal','adj','قانونی، حقوقی','/ˈliːɡəl/ · allowed by law','What the company has done is perfectly legal.','[["What the company has done is perfectly legal.","کاری که این شرکت انجام داده کاملا قانونی است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:legislation','legislation','n','قانون‌گذاری، قوانین','/ˌledʒəˈsleɪʃən/ · a law or set of laws','the legislation on abortion','[["the legislation on abortion","قانون سقط جنین"],["New legislation bans smoking indoors.","قانون جدید سیگار کشیدن در داخل خانه را ممنوع می‌کند."],["New legislation will protect endangered animals.","قانون جدید از حیوانات در حال انقراض محافظت می‌کند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:major','major','adj','اصلی، مهم، عمده','/ˈmeɪdʒər/ · main, important','The use of drugs is a major problem.','[["The use of drugs is a major problem.","استفاده از مواد مخدر یک مشکل اساسی است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:method','method','n','روش، شیوه','/ˈmeθəd/ · way, approach','traditional teaching methods','[["traditional teaching methods","روش‌های سنتی تدریس"],["This is an effective teaching method.","این یک روش آموزشی موثر است."],["There are many methods of learning vocabulary.","روش‌های زیادی برای یادگیری لغات وجود دارد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:occur','occur','v','رخ دادن، اتفاق افتادن','/əˈkɜːr/ · happen','The disease tends to occur in children under five.','[["The disease tends to occur in children under five.","این بیماری بیشتر در کودکان زیر پنج سال رخ می‌دهد."],["Earthquakes occur along fault lines.","زمین لرزه‌ها در امتداد خطوط گسل رخ می‌دهند."],["Earthquakes often occur in this region.","اغلب در این منطقه زلزله رخ می‌دهد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:percent','percent','n','درصد','/pərˈsent/ · per hundred (%)','New car sales may be down nineteen percent.','[["New car sales may be down nineteen percent.","فروش خودروهای جدید ممکن است نوزده درصد کاهش یابد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:period','period','n','دوره، مدت','/ˈpɪəriəd/ · a length of time','We had two power failures in a five-month period.','[["We had two power failures in a five-month period.","در یک دوره پنج ماهه دو قطع برق داشتیم."],["The Victorian period lasted over 60 years.","دوره ویکتوریا بیش از 60 سال به طول انجامید."],["The Safavid period was a golden age for Persian art.","دوره صفویه عصر طلایی برای هنر ایرانی بود."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:policy','policy','n','سیاست، خط‌مشی','/ˈpɒləsi/ · a way of doing sth','the government''s controversial economic policies','[["the government''s controversial economic policies","سیاست‌های اقتصادی بحث برانگیز دولت"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:principle','principle','n','اصل، قاعده','/ˈprɪnsəpəl/ · rule','the basic principles of business management','[["the basic principles of business management","اصول اساسی مدیریت کسب و کار"],["The machine works on a simple principle.","دستگاه بر اساس یک اصل ساده کار می‌کند."],["Equality is a fundamental principle of democracy.","برابری یک اصل اساسی دموکراسی است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:proceed','proceed','v','ادامه دادن، پیش رفتن','/prəˈsiːd/ · continue to do sth','Work is proceeding according to plan.','[["Work is proceeding according to plan.","کار طبق برنامه پیش می‌رود."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:process','process','n','فرایند، روند','/ˈprəʊses/ · a series of actions or steps','the aging process','[["the aging process","روند پیری"],["Photosynthesis is a complex process.","فتوسنتز یک فرآیند پیچیده است."],["Learning a language is a slow process.","یادگیری زبان فرآیندی کند است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:require','require','v','نیاز داشتن، لازم داشتن','/rɪˈkwaɪər/ · need','Most houseplants require regular watering.','[["Most houseplants require regular watering.","اکثر گیاهان آپارتمانی نیاز به آبیاری منظم دارند."],["The job requires good English.","این شغل به زبان انگلیسی خوب نیاز دارد."],["This job requires a lot of patience.","این کار به صبر و حوصله زیادی نیاز دارد."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:research','research','n','پژوهش، تحقیق؛ تحقیق کردن','/rɪˈsɜːtʃ/ · n., v. · serious study','I''m still doing research for my thesis.','[["I''m still doing research for my thesis.","من هنوز در حال تحقیق برای پایان نامه ام هستم."],["Research shows that sleep improves memory.","تحقیقات نشان می‌دهد که خواب حافظه را بهبود می‌بخشد."],["She is doing research on climate change.","او در حال انجام تحقیقات در مورد تغییرات آب و هوایی است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:response','response','n','پاسخ، واکنش','/rɪˈspɒns/ · n., v. · answer, reply','I am writing in response to your letter of July 17.','[["I am writing in response to your letter of July 17.","من در پاسخ به نامه 17 جولای شما می‌نویسم."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
