INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:specific','specific','adj','خاص، مشخص، ویژه','/spəˈsɪfɪk/ · particular','Could you be more specific about what you''re looking for?','[["Could you be more specific about what you''re looking for?","آیا می‌توانید در مورد آنچه به دنبال آن هستید دقیق‌تر بگویید؟"]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:structure','structure','n','ساختار، ساختمان','/ˈstrʌktʃər/ · n., v. · building or form','the structure of an atom','[["the structure of an atom","ساختار یک اتم"],["The structure of DNA is a double helix.","ساختار DNA یک مارپیچ دوگانه است."],["The structure of the human brain is very complex.","ساختار مغز انسان بسیار پیچیده است."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:theory','theory','n','نظریه، تئوری','/ˈθɪəri/ · hypothesis','Darwin''s theory of evolution','[["Darwin''s theory of evolution","نظریه تکامل داروین"],["Darwin developed the theory of evolution.","داروین نظریه تکامل را توسعه داد."],["In theory, the plan should work.","در تئوری، طرح باید کار کند."]]','awl',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
