INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:achieve','achieve','v','دست یافتن، به دست آوردن','/əˈtʃiːv/ · get, attain','They achieved high scores on their math tests.','[["They achieved high scores on their math tests.","آنها در آزمون‌های ریاضی خود نمرات بالایی کسب کردند."],["She achieved her goal of running a marathon.","او به هدف خود یعنی دوی ماراتن رسید."],["You can achieve a lot if you work hard.","اگر سخت کار کنید می‌توانید به موفقیت‌های زیادی برسید."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
