INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:acquisition','acquisition','n','اکتساب، فراگیری، به‌دست‌آوری','/ˌækwɪˈzɪʃn/ · achievement','the acquisition of language','[["the acquisition of language","فراگیری زبان"],["Language acquisition starts at birth.","فراگیری زبان از بدو تولد شروع می‌شود."],["Language acquisition is fastest in early childhood.","فراگیری زبان در اوایل کودکی سریع‌ترین است."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:affect','affect','v','تأثیر گذاشتن بر','/əˈfekt/ · influence','the areas affected by the hurricane','[["the areas affected by the hurricane","مناطق تحت تاثیر طوفان"],["Lack of sleep can affect your mood.","کمبود خواب می‌تواند بر خلق و خوی شما تأثیر بگذارد."],["The cold weather affected the crops.","هوای سرد بر محصولات زراعی تاثیر گذاشت."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
