INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:community','community','n','جامعه، اجتماع','/kəˈmjuːnəti/ · society','The festival was a great way for the local community to get together.','[["The festival was a great way for the local community to get together.","این جشنواره راهی عالی برای اجتماع محلی بود."],["The community built a new park.","جامعه یک پارک جدید ساخت."],["The library is the heart of our community.","کتابخانه قلب جامعه ماست."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
