INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:conduct','conduct','v','اجرا کردن، انجام دادن؛ رفتار','/kənˈdʌkt/ · v., n. · manage, behavior','We are conducting a survey of consumer attitudes towards organic food.','[["We are conducting a survey of consumer attitudes towards organic food.","ما در حال انجام یک نظرسنجی از نگرش مصرف کنندگان نسبت به مواد غذایی ارگانیک هستیم."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:consequence','consequence','n','پیامد، نتیجه','/ˈkɑːnsɪkwens/ · result','What were the economic consequences of the war?','[["What were the economic consequences of the war?","پیامدهای اقتصادی جنگ چه بود؟"],["Every decision has consequences.","هر تصمیمی عواقبی دارد."],["If you break the rules, you must accept the consequences.","اگر قوانین را زیر پا بگذارید، باید عواقب آن را بپذیرید."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:construct','construct','v','ساختن، بنا کردن','/kənˈstrʌkt/ · build','The hotel is currently under construction.','[["The hotel is currently under construction.","این هتل در حال حاضر در حال ساخت است."],["The bridge was constructed in 1890.","این پل در سال 1890 ساخته شد."],["Birds construct nests from twigs and grass.","پرندگان از شاخه‌ها و علف‌ها لانه می‌سازند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:consume','consume','v','مصرف کردن','/kənˈsuːm/ · use','Many consumers are not comfortable making purchases on the Internet.','[["Many consumers are not comfortable making purchases on the Internet.","بسیاری از مصرف کنندگان برای خرید از طریق اینترنت راحت نیستند."],["Cows consume a lot of grass.","گاوها علف زیادی مصرف می‌کنند."],["Cars consume a lot of fuel.","خودروها سوخت زیادی مصرف می‌کنند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
