INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:evaluate','evaluate','v','ارزیابی کردن','/ɪˈvæljueɪt/ · assess','We need to evaluate our options.','[["We need to evaluate our options.","ما باید گزینه‌های خود را ارزیابی کنیم."],["We need to evaluate the results.","ما باید نتایج را ارزیابی کنیم."],["Teachers evaluate students'' progress every term.","معلمان پیشرفت دانش آموزان را در هر ترم ارزیابی می‌کنند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:feature','feature','n','ویژگی، خصوصیت','/ˈfiːtʃər/ · characteristic','Air bags are a standard feature in most new cars.','[["Air bags are a standard feature in most new cars.","کیسه هوا یک ویژگی استاندارد در اکثر خودروهای جدید است."],["The app has many useful features.","این برنامه دارای بسیاری از ویژگی‌های مفید است."],["The tall towers are a feature of the city.","برج‌های بلند از ویژگی‌های این شهر هستند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
