INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:impact','impact','n','تأثیر، اثر','/ˈɪmpækt/ · influence','We need to assess the impact on climate change.','[["We need to assess the impact on climate change.","ما باید تاثیر آن بر تغییرات آب و هوایی را ارزیابی کنیم."],["Tourism has a big impact on the economy.","گردشگری تاثیر زیادی بر اقتصاد دارد."],["Technology has a huge impact on our lives.","تکنولوژی تاثیر زیادی بر زندگی ما دارد."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
