INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:invest','invest','v','سرمایه‌گذاری کردن','/ɪnˈvest/ · put money in sth','I''ve got a few thousand dollars to invest.','[["I''ve got a few thousand dollars to invest.","من چند هزار دلار برای سرمایه گذاری دارم."],["The country invested heavily in railways.","این کشور سرمایه گذاری زیادی در راه آهن انجام داد."],["He invested all his savings in the company.","او تمام پس انداز خود را در شرکت سرمایه گذاری کرد."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
