INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:select','select','v','انتخاب کردن، برگزیدن','/səˈlekt/ · choose, pick','The school will only select 12 applicants.','[["The school will only select 12 applicants.","مدرسه فقط 12 متقاضی را انتخاب می‌کند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
