INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:strategy','strategy','n','راهبرد، استراتژی','/ˈstrætɪdʒi/ · skilful planning','He was a genius when it came to military strategy.','[["He was a genius when it came to military strategy.","او در مورد استراتژی نظامی نابغه بود."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:survey','survey','n','نظرسنجی، بررسی؛ بررسی کردن','/ˈsɜːrveɪ/ · n., v. · poll','We conducted a survey of parents in the village.','[["We conducted a survey of parents in the village.","ما یک نظرسنجی از والدین در روستا انجام دادیم."],["A survey of 500 people was carried out.","نظرسنجی از 500 نفر انجام شد."],["A recent survey showed that most people want more parks.","یک نظرسنجی اخیر نشان داد که بیشتر مردم خواهان پارک‌های بیشتری هستند."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
