INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:traditional','traditional','adj','سنتی','/trəˈdɪʃənl/ · following old customs or beliefs · ≠ modern','He has a traditional view of women.','[["He has a traditional view of women.","او نگاه سنتی به زن دارد."],["Nowruz is a traditional celebration.","نوروز یک جشن سنتی است."],["We wore traditional clothes for the festival.","برای جشن لباس سنتی پوشیدیم."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:transfer','transfer','v','منتقل کردن، انتقال دادن','/trænsˈfɜːr/ · move','I''d like to transfer $500 to my checking account.','[["I''d like to transfer $500 to my checking account.","من می‌خواهم 500 دلار به حساب جاری خود منتقل کنم."]]','awl',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:alternative','alternative','adj','جایگزین، گزینه','/ɒːlˈtɜːrnətɪv/ · adj., n. · option, choice','Have you any alternative suggestions?','[["Have you any alternative suggestions?","آیا پیشنهاد جایگزینی دارید؟"],["Cycling is a healthy alternative to driving.","دوچرخه سواری جایگزین سالمی برای رانندگی است."],["We need to find an alternative to plastic bags.","ما باید جایگزینی برای کیسه‌های پلاستیکی پیدا کنیم."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:circumstance','circumstance','n','شرایط، موقعیت','/ˈsɜːrkəmstæns/ · situation','The circumstances of his death are suspicious.','[["The circumstances of his death are suspicious.","شرایط مرگ او مشکوک است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:comment','comment','v','اظهار نظر، توضیح؛ نظر دادن','/ˈkɒment/ · v., n. · note, remark','The plans were sent to the council for comment.','[["The plans were sent to the council for comment.","این طرح‌ها برای اظهار نظر به شورا ارسال شد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:compensate','compensate','v','جبران کردن','/ˈkɒmpənseɪt/ · make up for','He is seeking compensation for injuries suffered at work.','[["He is seeking compensation for injuries suffered at work.","او به دنبال جبران صدمات ناشی از کار است."],["Some animals compensate for poor sight with hearing.","برخی از حیوانات ضعف بینایی را با شنوایی جبران می‌کنند."],["Nothing can compensate for the loss of a child.","هیچ چیز نمی‌تواند فقدان یک کودک را جبران کند."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:component','component','n','جزء، مؤلفه','/kəmˈpəʊnənt/ · element, part','Companies make electronic components for computers.','[["Companies make electronic components for computers.","شرکت‌ها قطعات الکترونیکی را برای کامپیوترها تولید می‌کنند."],["The factory produces components for cars.","این کارخانه قطعات خودرو را تولید می‌کند."],["Trust is a key component of any relationship.","اعتماد جزء اصلی هر رابطه است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:consent','consent','v','رضایت؛ رضایت دادن','/kənˈsent/ · v., n. · allow, permit','He was reluctant at first but finally consented.','[["He was reluctant at first but finally consented.","او ابتدا تمایلی نداشت اما در نهایت رضایت داد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:considerable','considerable','adj','قابل توجه، زیاد','/kənˈsɪdərəbəl/ · noticeable','We''ve saved a considerable amount of money.','[["We''ve saved a considerable amount of money.","ما مقدار قابل توجهی پول پس انداز کرده ایم."],["The project needs considerable investment.","این پروژه نیاز به سرمایه گذاری قابل توجهی دارد."],["The project cost a considerable amount of money.","این پروژه هزینه قابل توجهی داشته است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
