INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:constraint','constraint','n','محدودیت، قید','/kənˈstreɪnt/ · restriction','Constraints on spending have forced the company to rethink its plans.','[["Constraints on spending have forced the company to rethink its plans.","محدودیت‌های مخارج، شرکت را مجبور کرده تا در برنامه‌های خود تجدید نظر کند."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:contribute','contribute','v','کمک کردن، سهم داشتن','/kənˈtrɪbjuːt/ · participate, support','The agency is mainly financed from voluntary contributions.','[["The agency is mainly financed from voluntary contributions.","این آژانس عمدتاً از کمک‌های داوطلبانه تأمین می‌شود."],["Everyone contributed to the project.","همه در این پروژه مشارکت داشتند."],["Pollution contributes to climate change.","آلودگی به تغییرات آب و هوایی کمک می‌کند."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
