INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:coordination','coordination','n','هماهنگی','/koʊˌɔːrdɪˈneɪʃn/ · working together','There needs to be better coordination between departments.','[["There needs to be better coordination between departments.","باید هماهنگی بهتری بین بخش‌ها وجود داشته باشد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
