INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:criteria','criteria','n','معیارها، ملاک‌ها','/kraɪˈtɪəriə/ · standards','the criteria we use to select candidates','[["the criteria we use to select candidates","معیارهایی که برای انتخاب نامزدها استفاده می‌کنیم"],["Applicants must meet strict criteria.","متقاضیان باید معیارهای سختگیرانه را رعایت کنند."],["What criteria are used to judge the competition?","برای قضاوت در مسابقه از چه معیارهایی استفاده می‌شود؟"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
