INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:demonstrate','demonstrate','v','نشان دادن، اثبات کردن','/ˈdemənstreɪt/ · show','These figures clearly demonstrate the size of the economic problem.','[["These figures clearly demonstrate the size of the economic problem.","این ارقام به وضوح اندازه مشکل اقتصادی را نشان می‌دهد."],["The study demonstrates the value of exercise.","این مطالعه ارزش ورزش را نشان می‌دهد."],["The teacher demonstrated how to use the microscope.","معلم نحوه استفاده از میکروسکوپ را نشان داد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
