INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:dominant','dominant','adj','غالب، مسلط','/ˈdɒmɪnənt/ · superior','The company is now dominant in its market.','[["The company is now dominant in its market.","این شرکت اکنون در بازار خود مسلط است."],["The lion is the dominant animal in the group.","شیر حیوان غالب این گروه است."],["Lions are the dominant animals in the savanna.","شیرها حیوانات غالب در ساوانا هستند."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
