INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:imply','imply','v','دلالت کردن، به‌طور ضمنی اشاره کردن','/ɪmˈplaɪ/ · hint, suggest','Early reports implied that the judge''s death was not an accident.','[["Early reports implied that the judge''s death was not an accident.","گزارش‌های اولیه حاکی از آن است که مرگ قاضی یک تصادف نبوده است."],["His silence implied agreement.","سکوت او به معنای توافق بود."],["The results imply that the drug is effective.","نتایج حاکی از موثر بودن دارو است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
