INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:interaction','interaction','n','تعامل، کنش متقابل','/ˌɪntərˈækʃən/ · a mutual action','Price is determined through the interaction of demand and supply.','[["Price is determined through the interaction of demand and supply.","قیمت از طریق تعامل تقاضا و عرضه تعیین می‌شود."],["Social interaction is vital for children.","تعامل اجتماعی برای کودکان حیاتی است."],["Online learning reduces face-to-face interaction.","یادگیری آنلاین تعامل چهره به چهره را کاهش می‌دهد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:justify','justify','v','توجیه کردن','/ˈdʒʌstɪfaɪ/ · explain, rationalize','He tried to present a justification for his behavior.','[["He tried to present a justification for his behavior.","سعی کرد توجیهی برای رفتارش ارائه کند."],["Can the high cost be justified?","آیا هزینه بالا قابل توجیه است؟"],["How can you justify spending so much money?","چگونه می‌توانید خرج کردن این همه پول را توجیه کنید؟"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
