INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:outcome','outcome','n','نتیجه، پیامد','/ˈaʊtkʌm/ · result','It was impossible to predict the outcome of the election.','[["It was impossible to predict the outcome of the election.","پیش بینی نتیجه انتخابات غیرممکن بود."],["The outcome of the experiment was surprising.","نتیجه آزمایش شگفت آور بود."],["Nobody can predict the outcome of the election.","هیچ کس نمی‌تواند نتیجه انتخابات را پیش بینی کند."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
