INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:register','register','v','ثبت‌نام کردن، ثبت کردن','/ˈredʒɪstər/ · enroll','How many students have registered for English classes?','[["How many students have registered for English classes?","چند دانش آموز در کلاس‌های زبان انگلیسی ثبت نام کرده اند؟"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:reliance','reliance','n','اتکا، وابستگی','/rɪˈlaɪəns/ · dependence','The region''s reliance on tourism has only grown in recent years.','[["The region''s reliance on tourism has only grown in recent years.","اتکای منطقه به گردشگری تنها در سال‌های اخیر افزایش یافته است."],["Our reliance on fossil fuels must end.","اتکای ما به سوخت‌های فسیلی باید پایان یابد."],["Our reliance on cars causes pollution.","اتکای ما به خودرو باعث آلودگی می‌شود."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:remove','remove','v','برداشتن، حذف کردن','/rɪˈmuːv/ · omit, cut out','Remove the old wallpaper and fill any holes in the walls.','[["Remove the old wallpaper and fill any holes in the walls.","کاغذ دیواری قدیمی را بردارید و هر سوراخی را در دیوارها پر کنید."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:scheme','scheme','n','طرح، برنامه','/skiːm/ · plan','The company has a new scheme for insurance coverage.','[["The company has a new scheme for insurance coverage.","این شرکت یک طرح جدید برای پوشش بیمه ای دارد."],["The government introduced a recycling scheme.","دولت طرح بازیافت را معرفی کرد."],["A new pension scheme was launched.","طرح بازنشستگی جدید راه اندازی شد."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:sequence','sequence','n','توالی، ترتیب','/ˈsiːkwəns/ · order','Be careful to perform the actions in the correct sequence.','[["Be careful to perform the actions in the correct sequence.","مراقب باشید که اقدامات را به ترتیب صحیح انجام دهید."],["Put the events in the correct sequence.","وقایع را در ترتیب صحیح قرار دهید."],["The DNA sequence of the virus has been identified.","توالی DNA ویروس شناسایی شده است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:shift','shift','n','تغییر، جابه‌جایی؛ شیفت','/ʃɪft/ · change','a marked shift in attitudes towards women','[["a marked shift in attitudes towards women","تغییر چشمگیر نگرش نسبت به زنان"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:specify','specify','v','مشخص کردن، تعیین کردن','/ˈspesɪfaɪ/ · mark','Payments will be made for a specified month.','[["Payments will be made for a specified month.","پرداخت‌ها برای یک ماه مشخص انجام می‌شود."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:sufficient','sufficient','adj','کافی','/səˈfɪʃənt/ · enough · ≠ insufficient','He had an income which was sufficient for his needs.','[["He had an income which was sufficient for his needs.","درآمدی داشت که برای نیازهایش کافی بود."],["We have sufficient food for a week.","برای یک هفته غذای کافی داریم."],["We have sufficient time to finish the project.","زمان کافی برای اتمام پروژه داریم."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:task','task','n','وظیفه، تکلیف','/tæsk/ · duty','perform/ complete a task','[["perform/ complete a task","انجام / تکمیل یک کار"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:technical','technical','adj','فنی','/ˈteknɪkəl/ · relating to a complex process','Our staff will be available to give you technical support.','[["Our staff will be available to give you technical support.","کارکنان ما برای ارائه پشتیبانی فنی به شما در دسترس خواهند بود."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:technique','technique','n','فن، تکنیک، روش','/tekˈniːk/ · method','We learned some techniques for relieving stress.','[["We learned some techniques for relieving stress.","چند تکنیک برای رهایی از استرس یاد گرفتیم."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:technology','technology','n','فناوری، تکنولوژی','/tekˈnɒlədʒi/ · application of science to business','major new developments in satellite technology','[["major new developments in satellite technology","تحولات جدید عمده در فناوری ماهواره ای"],["Technology makes communication easier.","فناوری ارتباطات را آسان‌تر می‌کند."],["Technology has changed the way we learn.","تکنولوژی روش یادگیری ما را تغییر داده است."]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:valid','valid','adj','معتبر، موجه','/ˈvælɪd/ · true, authentic','a valid password/ excuse','[["a valid password/ excuse","رمز عبور / بهانه معتبر"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:volume','volume','n','حجم، مقدار؛ جلد (کتاب)','/ˈvɑːljəm/ · amount','The volume is too loud. Can you turn the volume down?','[["The volume is too loud. Can you turn the volume down?","صدا خیلی بلند است. میتونی صدا رو کم کنی؟"]]','awl',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:access','access','n','دسترسی','/ˈækses/ · right to use something','High-speed internet access has become a necessity.','[["High-speed internet access has become a necessity.","دسترسی به اینترنت پرسرعت به یک ضرورت تبدیل شده است."],["Many villages still lack access to clean water.","بسیاری از روستاها هنوز به آب سالم دسترسی ندارند."],["Students have free access to the library.","دسترسی دانش آموزان به کتابخانه رایگان است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:adequate','adequate','adj','کافی، مناسب','/ˈædɪkwət/ · sufficient · ≠ inadequate','He didn''t give an adequate answer to the question.','[["He didn''t give an adequate answer to the question.","او پاسخ مناسبی به این سوال نداد."],["The hotel offers adequate parking.","هتل دارای پارکینگ مناسب می‌باشد."],["The room was small but adequate for our needs.","اتاق کوچک بود اما برای نیازهای ما کافی بود."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:annual','annual','adj','سالانه','/ˈænjuəl/ · yearly, once a year','The school trip has become an annual event.','[["The school trip has become an annual event.","سفر مدرسه به یک رویداد سالانه تبدیل شده است."],["The annual rainfall here is low.","میزان بارندگی سالانه در اینجا کم است."],["The company holds an annual meeting in March.","این شرکت در ماه مارس یک مجمع سالانه برگزار می‌کند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:apparent','apparent','adj','آشکار، ظاهری','/əˈpærənt/ · evident','The other team''s superiority was apparent in the game.','[["The other team''s superiority was apparent in the game.","برتری تیم مقابل در بازی مشهود بود."],["For no apparent reason, he left.","بدون هیچ دلیل مشخصی رفت."],["It was apparent that he was tired.","معلوم بود که خسته است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:approximate','approximate','adj','تقریبی','/əˈprɑːksɪmət/ · estimated','What is the approximate number of students in a class?','[["What is the approximate number of students in a class?","تعداد تقریبی دانش آموزان یک کلاس چقدر است؟"]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:attitude','attitude','n','نگرش، طرز فکر','/ˈætɪtuːd/ · opinion and feeling','Pete''s attitude towards women really scares me.','[["Pete''s attitude towards women really scares me.","نگرش پیت نسبت به زنان واقعاً مرا می‌ترساند."],["She has a positive attitude.","او نگرش مثبتی دارد."],["She has a positive attitude towards her work.","او نگرش مثبتی نسبت به کارش دارد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:attribute','attribute','v','نسبت دادن','/əˈtrɪbjuːt/ · assign, allocate','She attributes her success to hard work and a little luck.','[["She attributes her success to hard work and a little luck.","او موفقیت خود را به سخت کوشی و کمی شانس نسبت می‌دهد."],["Scientists attribute the change to pollution.","دانشمندان این تغییر را به آلودگی نسبت می‌دهند."],["He attributes his success to hard work.","او موفقیت خود را مرهون سخت کوشی می‌داند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:civil','civil','adj','مدنی، غیرنظامی؛ مؤدب','/ˈsɪvl/ · polite, nonmilitary','She was barely civil to me.','[["She was barely civil to me.","او به سختی نسبت به من متمدن بود."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:code','code','n','کد، مجموعه قوانین','/kəʊd/ · a set of rules','Everyone has to follow code of ethics.','[["Everyone has to follow code of ethics.","همه باید از منشور اخلاقی پیروی کنند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:commitment','commitment','n','تعهد','/kəˈmɪtmənt/ · promise, obligation','Are you ready to make a long-term commitment?','[["Are you ready to make a long-term commitment?","آیا برای تعهد بلند مدت آماده اید؟"],["Learning a language requires commitment.","یادگیری زبان نیازمند تعهد است."],["The company has a strong commitment to quality.","این شرکت تعهد قوی به کیفیت دارد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:communication','communication','n','ارتباط، برقراری ارتباط','/kəˌmjuːnɪˈkeɪʃn/ · the process by which people exchange information','Good communication is vital in a large organization.','[["Good communication is vital in a large organization.","ارتباطات خوب در یک سازمان بزرگ حیاتی است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:concentration','concentration','n','تمرکز؛ غلظت','/ˌkɒnsənˈtreɪʃən/ · focus','Lack of concentration was a real problem.','[["Lack of concentration was a real problem.","عدم تمرکز یک مشکل واقعی بود."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:conference','conference','n','کنفرانس، همایش','/ˈkɑːnfərəns/ · a large formal meeting','After a brief conference with his aides, he left for the airport.','[["After a brief conference with his aides, he left for the airport.","او پس از یک کنفرانس کوتاه با دستیارانش راهی فرودگاه شد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:contrast','contrast','n','تضاد، تقابل؛ مقایسه کردن','/ˈkɒntrɑːst/ · n., v. · find the differences','Compare and contrast the two novels.','[["Compare and contrast the two novels.","این دو رمان را با هم مقایسه و مقایسه کنید."],["In contrast, sales in Asia rose.","در مقابل، فروش در آسیا افزایش یافت."],["There is a sharp contrast between rich and poor areas.","تضاد شدیدی بین مناطق غنی و فقیر وجود دارد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:cycle','cycle','n','چرخه','/ˈsaɪkəl/ · circle','The water is circled through the machine and reused.','[["The water is circled through the machine and reused.","آب از طریق دستگاه چرخانده شده و مجددا مورد استفاده قرار می‌گیرد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:debate','debate','v','بحث کردن، مناظره کردن','/dɪˈbeɪt/ · discuss','There has been much discussion about prices.','[["There has been much discussion about prices.","در مورد قیمت‌ها بحث‌های زیادی شده است."],["There is a heated debate about nuclear power.","بحث‌های داغی در مورد انرژی هسته ای وجود دارد."],["The debate lasted two hours.","این مناظره دو ساعت به طول انجامید."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
