INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:domestic','domestic','adj','داخلی؛ خانگی','/dəˈmestɪk/ · family, internal','Unfortunately his domestic life wasn''t very happy.','[["Unfortunately his domestic life wasn''t very happy.","متأسفانه زندگی خانگی او چندان شاد نبود."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:emerge','emerge','v','پدیدار شدن، ظاهر شدن','/ɪˈmɜːrdʒ/ · appear','The facts emerged after a lengthy investigation.','[["The facts emerged after a lengthy investigation.","حقایق پس از یک تحقیق طولانی آشکار شد."],["New species emerged after the ice age.","گونه‌های جدیدی پس از عصر یخبندان پدیدار شدند."],["The sun emerged from behind the clouds.","خورشید از پشت ابرها بیرون آمد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
