INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ethnic','ethnic','adj','قومی، نژادی','/ˈeθnɪk/ · racial, tribal','The school teaches pupils from different ethnic groups.','[["The school teaches pupils from different ethnic groups.","این مدرسه به دانش آموزانی از اقوام مختلف آموزش می‌دهد."],["The city has many ethnic groups.","این شهر دارای اقوام بسیاری است."],["Ethnic food is popular in big cities.","غذاهای قومی در شهرهای بزرگ رایج است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:goal','goal','n','هدف','/ɡoʊl/ · aim, target, objective','They achieved their aim of increasing sales by 5%.','[["They achieved their aim of increasing sales by 5%.","آنها به هدف خود برای افزایش فروش تا 5 درصد دست یافتند."],["My goal is to learn 1000 words.","هدف من یادگیری 1000 کلمه است."],["My goal is to speak English fluently.","هدف من این است که انگلیسی را روان صحبت کنم."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:grant','grant','v','اعطا کردن، پذیرفتن؛ کمک‌هزینه','/ɡrænt/ · admit, permit','My request was granted.','[["My request was granted.","درخواست من برآورده شد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:hence','hence','adv','از این رو، بنابراین','/hens/ · for this reason','His mother was Italian, hence his name - Luca.','[["His mother was Italian, hence his name - Luca.","مادر او ایتالیایی بود، از این رو نام او - لوکا."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:hypothesis','hypothesis','n','فرضیه','/haɪˈpɒθəsɪs/ · theory','One hypothesis is that the victim fell asleep while driving.','[["One hypothesis is that the victim fell asleep while driving.","یک فرضیه این است که قربانی هنگام رانندگی به خواب رفته است."],["The experiment supported their hypothesis.","این آزمایش فرضیه آنها را تایید کرد."],["The scientists tested their hypothesis in the lab.","دانشمندان فرضیه خود را در آزمایشگاه آزمایش کردند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:implement','implement','v','اجرا کردن، پیاده‌سازی کردن','/ˈɪmpləment/ · do, carry out','We have decided to implement the committee''s recommendations in full.','[["We have decided to implement the committee''s recommendations in full.","ما تصمیم گرفته ایم که توصیه‌های کمیته را به طور کامل اجرا کنیم."],["The policy was implemented in 2019.","این سیاست در سال 2019 اجرا شد."],["The school will implement the new rules next year.","این مدرسه سال آینده قوانین جدید را اجرا خواهد کرد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:implication','implication','n','پیامد، دلالت ضمنی','/ˌɪmplɪˈkeɪʃn/ · consequence','What are the implications of these proposals?','[["What are the implications of these proposals?","پیامدهای این پیشنهادات چیست؟"],["The new law has serious implications for farmers.","قانون جدید پیامدهای جدی برای کشاورزان دارد."],["What are the implications of the study?","پیامدهای مطالعه چیست؟"]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:impose','impose','v','تحمیل کردن، وضع کردن','/ɪmˈpəʊz/ · force','The government imposed a ban on the sale of ivory.','[["The government imposed a ban on the sale of ivory.","دولت ممنوعیت فروش عاج را وضع کرد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
