INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:phase','phase','n','مرحله، فاز','/feɪz/ · stage','The project will be done in three phases.','[["The project will be done in three phases.","این پروژه در سه فاز انجام خواهد شد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:predict','predict','v','پیش‌بینی کردن','/prɪˈdɪkt/ · foretell, forecast','Newspapers predicted that Davis would be re- elected.','[["Newspapers predicted that Davis would be re- elected.","روزنامه‌ها پیش بینی کردند که دیویس دوباره انتخاب خواهد شد."],["Experts predict more rain.","کارشناسان بارندگی بیشتری را پیش بینی می‌کنند."],["Nobody can predict the future.","هیچ کس نمی‌تواند آینده را پیش بینی کند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
