INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:professional','professional','adj','حرفه‌ای، متخصص','/prəˈfeʃənl/ · expert','Their music is both memorable and professional.','[["Their music is both memorable and professional.","موسیقی آنها هم خاطره انگیز و هم حرفه ای است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:project','project','n','پروژه، طرح','/ˈprɑːdʒekt/ · a planned piece of work','The scheme will now be extended after a successful pilot project.','[["The scheme will now be extended after a successful pilot project.","این طرح اکنون پس از یک پروژه آزمایشی موفق تمدید خواهد شد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:promote','promote','v','ترفیع دادن؛ ترویج کردن','/prəˈməʊt/ · move to higher rank','He was promoted to senior editor.','[["He was promoted to senior editor.","او به سردبیری ارشد ارتقا یافت."],["The campaign promotes healthy eating.","این کمپین تغذیه سالم را ترویج می‌کند."],["The campaign aims to promote healthy eating.","هدف این کمپین ترویج تغذیه سالم است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:regime','regime','n','رژیم، نظام حکومتی','/reɪˈʒiːm/ · government, diet','The new regime is sure to fall.','[["The new regime is sure to fall.","رژیم جدید قطعا سقوط خواهد کرد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:resolution','resolution','n','قطعنامه، تصمیم؛ حل (مسئله)','/ˌrezəˈluːʃn/ · a formal decision','The resolution was passed by a two-thirds majority.','[["The resolution was passed by a two-thirds majority.","این قطعنامه با اکثریت دو سوم به تصویب رسید."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:retain','retain','v','حفظ کردن، نگه داشتن','/rɪˈteɪn/ · keep','You have the right to retain possession of the goods.','[["You have the right to retain possession of the goods.","شما حق دارید که مالکیت کالا را حفظ کنید."],["Clay soil retains water well.","خاک رسی آب را به خوبی حفظ می‌کند."],["The town has retained its traditional character.","این شهر ویژگی سنتی خود را حفظ کرده است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:series','series','n','سری، مجموعه، رشته','/ˈsɪriːz/ · events coming one after another','The series of events that led to the outbreak of war','[["The series of events that led to the outbreak of war","مجموعه حوادثی که منجر به وقوع جنگ شد"]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:statistics','statistics','n','آمار','/stəˈtɪstɪks/ · a collection of numbers','There is no statistical evidence that the economy is recovering.','[["There is no statistical evidence that the economy is recovering.","هیچ شواهد آماری مبنی بر احیای اقتصاد وجود ندارد."],["Statistics show that crime has fallen.","آمارها نشان می‌دهد که جرم و جنایت کاهش یافته است."],["According to official statistics, unemployment is rising.","طبق آمار رسمی، بیکاری در حال افزایش است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:status','status','n','وضعیت، جایگاه','/ˈsteɪtəs, ˈstætəs/ · position','These documents have no legal position in Britain.','[["These documents have no legal position in Britain.","این اسناد در بریتانیا جایگاه قانونی ندارند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:stress','stress','v','تأکید کردن','/stres/ · emphasize','The report stressed that student math skills need to improve.','[["The report stressed that student math skills need to improve.","در این گزارش تاکید شده است که مهارت‌های ریاضی دانش آموزان باید بهبود یابد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:subsequent','subsequent','adj','بعدی، متعاقب','/ˈsʌbsɪkwənt/ · next, later','Subsequently, the drug was found to cause cancer.','[["Subsequently, the drug was found to cause cancer.","پس از آن مشخص شد که این دارو باعث سرطان می‌شود."],["Subsequent studies confirmed the result.","مطالعات بعدی نتیجه را تایید کرد."],["Subsequent research confirmed the results.","تحقیقات بعدی نتایج را تایید کرد."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:sum','sum','n','مبلغ، مقدار؛ مجموع','/sʌm/ · amount','We donated a small sum (of money) to the charity.','[["We donated a small sum (of money) to the charity.","مبلغ ناچیزی (پول) به خیریه اهدا کردیم."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:summary','summary','n','خلاصه','/ˈsʌməri/ · abstract','A brief summary is given on a separate sheet.','[["A brief summary is given on a separate sheet.","خلاصه ای مختصر در یک برگه جداگانه آورده شده است."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:undertake','undertake','v','بر عهده گرفتن، متعهد شدن','/ˌʌndərˈteɪk/ · promise to do','Sometimes I undertake more projects than I can finish.','[["Sometimes I undertake more projects than I can finish.","گاهی اوقات من بیش از آنچه می‌توانم به پایان برسانم پروژه‌هایی را انجام می‌دهم."],["The university undertook a major research project.","دانشگاه یک پروژه تحقیقاتی بزرگ را انجام داد."],["She undertook to finish the work by Friday.","او متعهد شد که کار را تا جمعه تمام کند."]]','awl',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
