INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:adjust','adjust','v','تنظیم کردن، تطبیق دادن','/əˈdʒʌst/ · adapt','It took time to adjust myself to motherhood.','[["It took time to adjust myself to motherhood.","زمان برد تا خودم را با مادری وفق دهم."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:alter','alter','v','تغییر دادن','/ˈɔːltər/ · change, adjust','The place has altered in the 10 years since I left.','[["The place has altered in the 10 years since I left.","این مکان در 10 سالی که من ترک کردم تغییر کرده است."],["Climate change alters habitats.","تغییر اقلیم زیستگاه‌ها را تغییر می‌دهد."],["Climate change could alter the ecosystem.","تغییرات آب و هوایی می‌تواند اکوسیستم را تغییر دهد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:amendment','amendment','n','اصلاحیه، اصلاح','/əˈmendmənt/ · revision, modification','Parliament approved an amendment to the Constitution.','[["Parliament approved an amendment to the Constitution.","مجلس اصلاحیه قانون اساسی را تصویب کرد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:aware','aware','adj','آگاه، مطلع','/əˈwer/ · conscious, informed','The children are aware of the danger of taking drugs.','[["The children are aware of the danger of taking drugs.","کودکان از خطر مصرف مواد آگاه هستند."],["Are you aware of the risks?","آیا از خطرات آن آگاه هستید؟"],["I wasn''t aware that the shop was closed.","نمیدونستم مغازه تعطیله"]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:capacity','capacity','n','ظرفیت، گنجایش؛ توانایی','/kəˈpæsəti/ · ability, size','The fuel tank has a capacity of 40 liters.','[["The fuel tank has a capacity of 40 liters.","ظرفیت مخزن سوخت 40 لیتر است."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:challenge','challenge','n','چالش','/ˈtʃælɪndʒ/ · a demanding situation','The new lawsuit challenges the lower court''s decision.','[["The new lawsuit challenges the lower court''s decision.","دعوای جدید تصمیم دادگاه بدوی را به چالش می‌کشد."],["Learning a new language is a challenge.","یادگیری یک زبان جدید یک چالش است."],["The new manager faces many challenges.","مدیر جدید با چالش‌های زیادی مواجه است."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:clause','clause','n','بند، ماده (قانون)','/klɔːz/ · an item in a legal document','A confidentiality clause was added to the contract.','[["A confidentiality clause was added to the contract.","یک بند محرمانه به قرارداد اضافه شد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:compound','compound','n','ترکیب، ماده مرکب','/ˈkɑːmpaʊnd/ · combination','Teaching is a compound of several different skills.','[["Teaching is a compound of several different skills.","آموزش ترکیبی از چندین مهارت مختلف است."],["Water is a compound of hydrogen and oxygen.","آب ترکیبی از هیدروژن و اکسیژن است."],["Scientists discovered a new compound.","دانشمندان ترکیب جدیدی کشف کردند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:conflict','conflict','n','تعارض، درگیری','/ˈkɒnflɪkt/ · opposition','Normal kids who are in conflict with their parents.','[["Normal kids who are in conflict with their parents.","بچه‌های عادی که با والدین خود در تعارض هستند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:consult','consult','v','مشورت کردن، رجوع کردن به','/kənˈsʌlt/ · exchange views, confer','I need to consult with my lawyer.','[["I need to consult with my lawyer.","باید با وکیلم مشورت کنم"]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:contact','contact','n','تماس، ارتباط','/ˈkɒntækt/ · the act of communicating with somebody','Many of us have no direct contact with elderly people.','[["Many of us have no direct contact with elderly people.","بسیاری از ما هیچ ارتباط مستقیمی با افراد مسن نداریم."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:decline','decline','n','کاهش؛ کاهش یافتن','/dɪˈklaɪn/ · n., v. · decrease','There has been a decline in the size of families.','[["There has been a decline in the size of families.","تعداد خانواده‌ها کاهش یافته است."],["The number of visitors declined in 2020.","تعداد بازدیدکنندگان در سال 2020 کاهش یافت."],["The number of birds has declined sharply.","تعداد پرندگان به شدت کاهش یافته است."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
