INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:enable','enable','v','قادر ساختن، امکان دادن','/ɪˈneɪbəl/ · make able','The loan enabled Jan to buy the house.','[["The loan enabled Jan to buy the house.","وام به جان این امکان را داد که خانه را بخرد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:energy','energy','n','انرژی، نیرو','/ˈenərdʒi/ · the ability to do work','Helping people takes time and energy.','[["Helping people takes time and energy.","کمک به مردم زمان و انرژی می‌خواهد."],["Solar energy is becoming cheaper.","انرژی خورشیدی ارزان‌تر می‌شود"],["Solar energy is clean and renewable.","انرژی خورشیدی پاک و تجدید پذیر است."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:enforce','enforce','v','اجرا کردن (قانون)، به اجرا گذاشتن','/ɪnˈfɔːrs/ · cause a law to be obeyed','The legislation will be difficult to enforce.','[["The legislation will be difficult to enforce.","اجرای این قانون دشوار خواهد بود."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:entity','entity','n','موجودیت، هستی','/ˈentəti/ · sth that exist as a single & complete unit','Church and empire were fused in a single entity.','[["Church and empire were fused in a single entity.","کلیسا و امپراتوری در یک موجودیت واحد ادغام شدند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:equivalent','equivalent','adj','معادل، هم‌ارز','/ɪˈkwɪvələnt/ · equal','Some regulations are equivalent to censorship.','[["Some regulations are equivalent to censorship.","برخی از مقررات معادل سانسور هستند."],["One kilometre is equivalent to about 0.62 miles.","یک کیلومتر معادل حدود 0.62 مایل است."],["There is no equivalent word in Persian.","در فارسی کلمه معادلی وجود ندارد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:evolution','evolution','n','تکامل','/ˌevəˈluːʃn/ · gradual development','Darwin''s theory of evolution','[["Darwin''s theory of evolution","نظریه تکامل داروین"],["Darwin developed the theory of evolution.","داروین نظریه تکامل را توسعه داد."],["The evolution of birds from dinosaurs is well documented.","تکامل پرندگان از دایناسورها به خوبی مستند شده است."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:expand','expand','v','گسترش دادن، گسترش یافتن','/ɪkˈspænd/ · grow, extend','a period of rapid economic expansion','[["a period of rapid economic expansion","دوره رشد سریع اقتصادی"],["The company plans to expand overseas.","این شرکت قصد دارد در خارج از کشور گسترش یابد."],["The company plans to expand into Asia.","این شرکت قصد دارد در آسیا گسترش یابد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:exposure','exposure','n','در معرض قرار گرفتن؛ آشکارسازی','/ɪkˈspəʊʒər/ · presentation','children''s exposure to violence on television','[["children''s exposure to violence on television","قرار گرفتن کودکان در معرض خشونت در تلویزیون"],["Exposure to sunlight is good for plants.","قرار گرفتن در معرض نور خورشید برای گیاهان مفید است."],["Long exposure to noise can damage hearing.","قرار گرفتن طولانی مدت در معرض صدا می‌تواند به شنوایی آسیب برساند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
