INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:facilitate','facilitate','v','تسهیل کردن','/fəˈsɪlɪteɪt/ · make easier, ease','Cutting taxes may facilitate economic recovery.','[["Cutting taxes may facilitate economic recovery.","کاهش مالیات ممکن است بهبود اقتصادی را تسهیل کند."],["The internet facilitates global trade.","اینترنت تجارت جهانی را تسهیل می‌کند."],["The new software will facilitate communication.","نرم افزار جدید ارتباطات را تسهیل می‌کند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:fundamental','fundamental','adj','بنیادی، اساسی','/ˌfʌndəˈmentl/ · basic, essential','We have to tackle the fundamental cause of the problem.','[["We have to tackle the fundamental cause of the problem.","ما باید با علت اساسی مشکل مقابله کنیم."],["Education is a fundamental right.","آموزش یک حق اساسی است."],["There are fundamental differences between the two systems.","تفاوت‌های اساسی بین این دو سیستم وجود دارد."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:generate','generate','v','تولید کردن، ایجاد کردن','/ˈdʒenəreɪt/ · produce','The wind turbines are used to generate electricity.','[["The wind turbines are used to generate electricity.","از توربین‌های بادی برای تولید برق استفاده می‌شود."],["The new factory will generate hundreds of jobs.","کارخانه جدید صدها شغل ایجاد خواهد کرد."],["Solar panels generate power from sunlight.","پنل‌های خورشیدی از نور خورشید انرژی تولید می‌کنند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:generation','generation','n','نسل','/ˌdʒenəˈreɪʃn/ · same age group','My generation have grown up with the internet.','[["My generation have grown up with the internet.","نسل من با اینترنت بزرگ شده است."],["The younger generation uses smartphones daily.","نسل جوان روزانه از گوشی‌های هوشمند استفاده می‌کند."],["The younger generation uses technology every day.","نسل جوان هر روز از فناوری استفاده می‌کند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
