INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:mental','mental','adj','ذهنی، روانی','/ˈmentl/ · involving the mind or intellectual processes','The very old man still had all his mental powers.','[["The very old man still had all his mental powers.","مرد بسیار پیر هنوز تمام قوای ذهنی خود را داشت."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:modify','modify','v','اصلاح کردن، تغییر دادن','/ˈmɑːdɪfaɪ/ · change','The regulations can only be modified by a special committee.','[["The regulations can only be modified by a special committee.","این مقررات فقط توسط یک کمیته ویژه قابل تغییر است."],["The plan was modified after the test.","این طرح پس از آزمایش اصلاح شد."],["Scientists modified the genes of the plant.","دانشمندان ژن‌های این گیاه را اصلاح کردند."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:monitor','monitor','v','نظارت کردن، پایش کردن','/ˈmɑːnɪtər/ · supervise, observe','The temperature is carefully monitored.','[["The temperature is carefully monitored.","دما به دقت کنترل می‌شود."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
