INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:notion','notion','n','مفهوم، تصور','/ˈnəʊʃn/ · concept','He has some pretty strange notions.','[["He has some pretty strange notions.","او تصورات بسیار عجیبی دارد."],["The notion that the Earth is flat was rejected.","این تصور که زمین مسطح است رد شد."],["I have no notion of what he means.","من نمی‌دانم منظور او چیست."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
