INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:orientation','orientation','n','جهت‌گیری، گرایش','/ˌɒriənˈteɪʃən/ · location or direction','How can we get students to adopt a serious orientation to learning?','[["How can we get students to adopt a serious orientation to learning?","چگونه می‌توانیم دانش آموزان را وادار کنیم که جهت گیری جدی برای یادگیری اتخاذ کنند؟"]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:perspective','perspective','n','دیدگاه، چشم‌انداز','/pəˈspektɪv/ · viewpoint','His father''s death gave him a whole new perspective on life.','[["His father''s death gave him a whole new perspective on life.","مرگ پدرش به او دیدگاه جدیدی نسبت به زندگی داد."],["Travel gives you a new perspective.","سفر به شما دیدگاه جدیدی می‌دهد."],["Try to see the problem from a different perspective.","سعی کنید مشکل را از منظر دیگری ببینید."]]','awl',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
