INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:acknowledge','acknowledge','v','تصدیق کردن، اذعان کردن','/əkˈnɒlɪdʒ/ · admit, recognize','Claire acknowledged that she was guilty.','[["Claire acknowledged that she was guilty.","کلر اعتراف کرد که مقصر است."],["He acknowledged his mistake.","او به اشتباه خود اعتراف کرد."],["He acknowledged that he had made a mistake.","او اعتراف کرد که اشتباه کرده است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:aggregate','aggregate','v','مجموع، کل؛ جمع کردن','/ˈæɡrɪɡət/ · v., n. · collect, amount','They purchased an aggregate of 3000 shares in the company.','[["They purchased an aggregate of 3000 shares in the company.","آنها مجموعاً 3000 سهام شرکت را خریداری کردند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:allocate','allocate','v','تخصیص دادن، اختصاص دادن','/ˈæləkeɪt/ · give,assign','The government allocated enough funds to infrastructures.','[["The government allocated enough funds to infrastructures.","دولت بودجه کافی به زیرساخت‌ها اختصاص داد."],["The council allocated funds to new schools.","شورا بودجه ای را به مدارس جدید اختصاص داد."],["The government allocated more money to education.","دولت بودجه بیشتری به آموزش و پرورش اختصاص داد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:assign','assign','v','واگذار کردن، تعیین کردن','/əˈsaɪn/ · designate','UN troops were assigned the task of rebuilding the hospital.','[["UN troops were assigned the task of rebuilding the hospital.","وظیفه بازسازی بیمارستان به نیروهای سازمان ملل واگذار شد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:attach','attach','v','پیوست کردن، ضمیمه کردن','/əˈtætʃ/ · v., n. · fasten, join · ≠ detach','Please complete the attached form.','[["Please complete the attached form.","لطفا فرم پیوست را تکمیل نمایید."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:author','author','n','نویسنده، مؤلف','/ˈɒːθər/ · writer','He is the author of three books on art.','[["He is the author of three books on art.","او نویسنده سه کتاب در زمینه هنر است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:bond','bond','n','پیوند، رابطه','/bɑːnd/ · relationship, friendship','In societies with strong family bonds, people tend to live longer.','[["In societies with strong family bonds, people tend to live longer.","در جوامعی که پیوندهای خانوادگی قوی دارند، مردم بیشتر عمر می‌کنند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:brief','brief','adj','کوتاه، مختصر','/briːf/ · short, quick','We had a brief conversation because he was in a hurry.','[["We had a brief conversation because he was in a hurry.","چون عجله داشت صحبت کوتاهی داشتیم."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:capable','capable','adj','توانا، قادر','/ˈkeɪpəbl/ · able','She''s a very capable woman/worker/judge.','[["She''s a very capable woman/worker/judge.","او یک زن / کارگر / قاضی بسیار توانا است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:cite','cite','v','استناد کردن، ذکر کردن','/saɪt/ · mention, quote','She cited 3 reasons why people get into debt.','[["She cited 3 reasons why people get into debt.","او به 3 دلیل برای بدهکاری مردم اشاره کرد."],["The report cites several studies.","در این گزارش به چندین مطالعه اشاره شده است."],["She cited lack of time as the reason.","او دلیل آن را کمبود وقت عنوان کرد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:cooperative','cooperative','adj','همکار، تعاونی؛ همکاری‌کننده','/kəʊˈɑːpərətɪv/ · collaborative, synergic','A cooperative international effort is needed.','[["A cooperative international effort is needed.","یک تلاش مشترک بین المللی مورد نیاز است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:discrimination','discrimination','n','تبعیض','/dɪˌskrɪmɪˈneɪʃn/ · prejudice, bias','victims of racial discrimination','[["victims of racial discrimination","قربانیان تبعیض نژادی"],["Laws protect workers against discrimination.","قوانین از کارگران در برابر تبعیض حمایت می‌کند."],["Discrimination based on gender is illegal.","تبعیض جنسیتی غیرقانونی است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:display','display','v','نمایش دادن','/dɪˈspleɪ/ · exhibit, show','Family photographs were displayed on the wall.','[["Family photographs were displayed on the wall.","عکس‌های خانوادگی روی دیوار نصب شده بود."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:diversity','diversity','n','تنوع','/daɪˈvɜːrsəti/ · variety','There was considerable diversity in the style of the reports.','[["There was considerable diversity in the style of the reports.","تنوع قابل توجهی در سبک گزارش‌ها وجود داشت."],["The rainforest has an amazing diversity of plants.","جنگل‌های بارانی دارای تنوع شگفت انگیزی از گیاهان است."],["The city is proud of its cultural diversity.","این شهر به تنوع فرهنگی خود افتخار می‌کند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:domain','domain','n','حوزه، قلمرو','/dəʊˈmeɪn/ · area, realm','These documents are in the public domain.','[["These documents are in the public domain.","این اسناد در حوزه عمومی هستند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:edition','edition','n','ویرایش، چاپ','/ɪˈdɪʃn/ · printing, revision','The fifth edition of IELTS Success appeared in 1401.','[["The fifth edition of IELTS Success appeared in 1401.","پنجمین ویرایش IELTS Success در سال 1401 ظاهر شد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:enhance','enhance','v','افزایش دادن، بهبود بخشیدن','/ɪnˈhæns/ · increase, improve','Rarity enhances the worth of old coins.','[["Rarity enhances the worth of old coins.","نادر بودن ارزش سکه‌های قدیمی را افزایش می‌دهد."],["Technology can enhance learning.","فناوری می‌تواند یادگیری را تقویت کند."],["Good lighting can enhance the beauty of a room.","نور خوب می‌تواند زیبایی یک اتاق را افزایش دهد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:estate','estate','n','املاک، دارایی','/ɪˈsteɪt/ · money and property','She left her entire estate to her niece.','[["She left her entire estate to her niece.","او تمام دارایی خود را به خواهرزاده اش واگذار کرد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:exceed','exceed','v','فراتر رفتن از، تجاوز کردن از','/ɪkˈsiːd/ · go beyond, surpass','Economic growth exceeded expectations this year.','[["Economic growth exceeded expectations this year.","رشد اقتصادی امسال فراتر از انتظار بود."],["The cost exceeded our budget.","هزینه بیشتر از بودجه ما بود."],["Do not exceed the speed limit.","از حد مجاز سرعت تجاوز نکنید."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:expert','expert','adj','متخصص، کارشناس','/ˈekspɜːrt/ · professional','I have a friend who is very expert at the language','[["I have a friend who is very expert at the language","من دوستی دارم که در این زبان بسیار متخصص است"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:explicit','explicit','adj','صریح، روشن','/ɪkˈsplɪsɪt/ · clear','He was quite explicit as to what he expected us to do for him.','[["He was quite explicit as to what he expected us to do for him.","او کاملاً صریح بود که انتظار داشت ما برای او چه کاری انجام دهیم."],["The instructions were explicit.","دستورالعمل‌ها صریح بود."],["He made an explicit promise.","قول صریح داد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:federal','federal','adj','فدرال، مربوط به دولت مرکزی','/ˈfedərəl/ · relating to the central government of a country','The US has local, state, and federal courts.','[["The US has local, state, and federal courts.","ایالات متحده دارای دادگاه‌های محلی، ایالتی و فدرال است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:fee','fee','n','هزینه، کارمزد، شهریه','/fiː/ · price, charge','Tuition fees have now reached $9000 a year.','[["Tuition fees have now reached $9000 a year.","هزینه تحصیل در حال حاضر به 9000 دلار در سال رسیده است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:flexible','flexible','adj','انعطاف‌پذیر','/ˈfleksəbl/ · adaptable, elastic','My schedule is quite flexible.','[["My schedule is quite flexible.","برنامه من کاملاً منعطف است."],["I have a flexible work schedule.","من یک برنامه کاری انعطاف پذیر دارم."],["My working hours are very flexible.","ساعت کاری من بسیار انعطاف پذیر است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:furthermore','furthermore','adv','علاوه بر این، به‌علاوه','/ˌfɜːrðərˈmɔːr/ · moreover','Candy costs money; furthermore, it''s bad for you.','[["Candy costs money; furthermore, it''s bad for you.","آب نبات هزینه دارد. علاوه بر این، برای شما بد است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:gender','gender','n','جنسیت','/ˈdʒendər/ · sex','discrimination on the basis of race, gender or age','[["discrimination on the basis of race, gender or age","تبعیض بر اساس نژاد، جنسیت یا سن"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ignore','ignore','v','نادیده گرفتن','/ɪɡˈnɔːr/ · neglect, pay no attention to','She can be really irritating but I try to ignore her.','[["She can be really irritating but I try to ignore her.","او می‌تواند واقعاً تحریک کننده باشد اما من سعی می‌کنم او را نادیده بگیرم."],["She ignored his rude comment.","او نظر بی ادبانه او را نادیده گرفت."],["She ignored my advice and went anyway.","او به توصیه من توجهی نکرد و به هر حال رفت."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:incentive','incentive','n','انگیزه، مشوق','/ɪnˈsentɪv/ · motivation','There is no incentive for people to save fuel.','[["There is no incentive for people to save fuel.","هیچ انگیزه ای برای مردم برای صرفه جویی در مصرف سوخت وجود ندارد."],["Tax incentives encourage green energy.","مشوق‌های مالیاتی انرژی سبز را تشویق می‌کند."],["Tax breaks are an incentive for companies to invest.","معافیت‌های مالیاتی انگیزه ای برای شرکت‌ها برای سرمایه گذاری است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:incidence','incidence','n','میزان وقوع، شیوع','/ˈɪnsɪdəns/ · occurrence, rate','an area with a high incidence of crime','[["an area with a high incidence of crime","منطقه ای با وقوع جرم بالا"],["The incidence of heart disease is higher in cities.","بروز بیماری‌های قلبی در شهرها بیشتر است."],["There is a low incidence of crime in the village.","میزان وقوع جرم در روستا کم است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:incorporate','incorporate','v','گنجاندن، ادغام کردن','/ɪnˈkɔːrpəreɪt/ · include, contain','His book incorporates all his thinking on the subject.','[["His book incorporates all his thinking on the subject.","کتاب او تمام افکار او را در مورد این موضوع در بر می‌گیرد."],["The new design incorporates solar panels.","طراحی جدید شامل پنل‌های خورشیدی است."],["The course incorporates practical training.","این دوره شامل آموزش عملی است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:index','index','n','فهرست، نمایه؛ شاخص','/ˈɪndeks/ · list, directory','Try looking up ''heart disease'' in the index.','[["Try looking up ''heart disease'' in the index.","سعی کنید «بیماری قلبی» را در فهرست جستجو کنید."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:inhibit','inhibit','v','مانع شدن، بازداشتن','/ɪnˈhɪbɪt/ · prevent, prohibit','the obstacles which inhibit change','[["the obstacles which inhibit change","موانعی که مانع از تغییر می‌شوند"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:initiative','initiative','n','ابتکار عمل، ابتکار','/ɪˈnɪʃətɪv/ · the power, energy, or ability to organize or accomplish something','use your initiative, imagination, and common sense','[["use your initiative, imagination, and common sense","از ابتکار، تخیل و عقل سلیم خود استفاده کنید"],["The recycling initiative was a success.","ابتکار بازیافت موفقیت آمیز بود."],["The new initiative aims to reduce youth unemployment.","هدف ابتکار جدید کاهش بیکاری جوانان است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:input','input','n','ورودی، داده','/ˈɪnpʊt/ · data, feed in','The power input will come largely from hydroelectricity.','[["The power input will come largely from hydroelectricity.","انرژی ورودی عمدتاً از برق آبی تامین می‌شود."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:instructions','instructions','n','دستورالعمل‌ها','/ɪnˈstrʌkʃən/ · directions, orders','Always read the instructions before switching on the machine.','[["Always read the instructions before switching on the machine.","همیشه قبل از روشن کردن دستگاه دستورالعمل‌ها را بخوانید."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:intelligent','intelligent','adj','باهوش','/ɪnˈtelədʒənt/ · smart, clever, bright','She asked a lot of intelligent questions.','[["She asked a lot of intelligent questions.","او سوالات هوشمندانه زیادی پرسید."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:interval','interval','n','فاصله، وقفه','/ˈɪntərvəl/ · period of time between 2 events','We see each other at regular intervals -once a month.','[["We see each other at regular intervals -once a month.","ما همدیگر را در فواصل منظم - ماهی یک بار - می‌بینیم."],["Trees were planted at regular intervals.","درختان در فواصل منظم کاشته شدند."],["The buses run at ten-minute intervals.","اتوبوس‌ها در فواصل ده دقیقه ای حرکت می‌کنند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:lecture','lecture','n','سخنرانی، درس','/ˈlektʃər/ · speech or talk','He spent the year lecturing to various student groups.','[["He spent the year lecturing to various student groups.","او سال را به سخنرانی در گروه‌های مختلف دانشجویی گذراند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:migrate','migrate','v','مهاجرت کردن، کوچ کردن','/ˈmaɪɡreɪt/ · to move from one place to another','Swallows migrate south in winter.','[["Swallows migrate south in winter.","پرستوها در زمستان به جنوب مهاجرت می‌کنند."],["Many birds migrate south in winter.","بسیاری از پرندگان در زمستان به جنوب مهاجرت می‌کنند."],["Salmon migrate up rivers to lay their eggs.","ماهی قزل آلا برای تخم گذاری به رودخانه‌ها مهاجرت می‌کند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:minimum','minimum','adj','حداقل، کمینه','/ˈmɪnɪməm/ · adj., adv. · least','This can be done with the minimum amount of effort.','[["This can be done with the minimum amount of effort.","این را می‌توان با حداقل تلاش انجام داد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ministry','ministry','n','وزارتخانه','/ˈmɪnɪstri/ · government department','the ministry of Defense','[["the ministry of Defense","وزارت دفاع"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:motivation','motivation','n','انگیزه','/ˌməʊtɪˈveɪʃn/ · incentive, force','Her motivation for quitting her job was unclear.','[["Her motivation for quitting her job was unclear.","انگیزه او برای ترک شغلش نامشخص بود."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:neutral','neutral','adj','بی‌طرف، خنثی','/ˈnuːtrəl/ · impartial, unbiased','When her friends had a quarrel, she remained neutral.','[["When her friends had a quarrel, she remained neutral.","وقتی دوستانش دعوا می‌کردند، بی طرف می‌ماند."],["Switzerland remained neutral during the war.","سوئیس در طول جنگ بی طرف ماند."],["Pure water is chemically neutral.","آب خالص از نظر شیمیایی خنثی است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:nevertheless','nevertheless','adv','با این حال، با وجود این','/ˌnevərðəˈles/ · in spite of, despite','He forgot to study; nevertheless, he must take the exam.','[["He forgot to study; nevertheless, he must take the exam.","درس خواندن را فراموش کرد با این حال، او باید در امتحان شرکت کند."],["It was raining; nevertheless, we went out.","باران می‌بارید؛ با این حال رفتیم بیرون"],["The task was difficult; nevertheless, they finished it.","کار دشوار بود؛ با این حال آنها آن را تمام کردند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:overseas','overseas','adj','خارجی، ماورای دریا','/ˌəʊvərˈsiːz/ · abroad, foreign','There are a lot of overseas students in Cambridge.','[["There are a lot of overseas students in Cambridge.","تعداد زیادی از دانشجویان خارج از کشور در کمبریج وجود دارد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:precede','precede','v','مقدم بودن بر، پیش از چیزی آمدن','/prɪˈsiːd/ · come before, come first','in the moments which immediately preceded the earthquake','[["in the moments which immediately preceded the earthquake","در لحظاتی که بلافاصله قبل از زلزله بود"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:presume','presume','v','فرض کردن، گمان کردن','/prɪˈzuːm/ · assume, suppose','There is no scientific evidence to support such presumptions.','[["There is no scientific evidence to support such presumptions.","هیچ مدرک علمی برای حمایت از چنین فرضیاتی وجود ندارد."],["I presume you have read the report.","من فکر می‌کنم شما گزارش را خوانده اید."],["The ship was presumed lost.","گمان می‌رفت کشتی گم شده است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:rational','rational','adj','منطقی، معقول','/ˈræʃnəl/ · reasonable, logical','There is no rational explanation for his actions.','[["There is no rational explanation for his actions.","هیچ توضیح منطقی برای اعمال او وجود ندارد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:recovery','recovery','n','بهبود، بازیابی','/rɪˈkʌvəri/ · return to health, comeback','Doctors expect him to make a full recovery.','[["Doctors expect him to make a full recovery.","پزشکان انتظار دارند که او بهبودی کامل پیدا کند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:reveal','reveal','v','آشکار کردن، فاش کردن','/rɪˈviːl/ · make known, describe','A series of flashbacks reveal the details of the tragedy.','[["A series of flashbacks reveal the details of the tragedy.","یک سری فلاش بک جزئیات فاجعه را آشکار می‌کند."],["The report revealed some surprising facts.","این گزارش حقایق شگفت انگیزی را فاش کرد."],["The investigation revealed new information.","تحقیقات اطلاعات جدیدی را فاش کرد."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:scope','scope','n','دامنه، گستره','/skəʊp/ · potential, range','A full discussion of that issue is beyond the scope of this book.','[["A full discussion of that issue is beyond the scope of this book.","بحث کامل درباره آن موضوع از حوصله این کتاب خارج است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:subside','subside','v','فروکش کردن، فرو نشستن','/səbˈsaɪd/ · go back, sink','She waited for his anger subside.','[["She waited for his anger subside.","منتظر بود تا عصبانیتش فروکش کند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:tape','tape','n','نوار','/teɪp/ · cassette','Bring me a blank tape and I''ll record it for you.','[["Bring me a blank tape and I''ll record it for you.","یک نوار سفید برای من بیاور تا برایت ضبط کنم."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:trace','trace','v','ردیابی کردن، پیدا کردن','/treɪs/ · find, detect','We finally traced him to an address in Mashhad!','[["We finally traced him to an address in Mashhad!","بالاخره ردش را به آدرسی در مشهد رساندیم!"]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:transformation','transformation','n','دگرگونی، تحول','/ˌtrænsfəˈmeɪʃən/ · change, convert','transformation from dictatorship to democracy','[["transformation from dictatorship to democracy","تبدیل از دیکتاتوری به دموکراسی"],["The city has undergone a complete transformation.","این شهر دستخوش دگرگونی کامل شده است."],["The transformation of a caterpillar into a butterfly is amazing.","تبدیل کاترپیلار به پروانه شگفت انگیز است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:transport','transport','v','حمل کردن، جابه‌جا کردن','/ˈtrænspɔːrt/ · carry, transfer','The company will arrange transport from the airport.','[["The company will arrange transport from the airport.","این شرکت حمل و نقل از فرودگاه را ترتیب خواهد داد."],["Public transport should be free.","حمل و نقل عمومی باید رایگان باشد"],["Public transport in the city is cheap and fast.","حمل و نقل عمومی در شهر ارزان و سریع است."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:underlying','underlying','adj','اساسی، زیربنایی','/ˌʌndərˈlaɪɪŋ/ · basic, essential','Stress is the underlying cause of many illnesses.','[["Stress is the underlying cause of many illnesses.","استرس عامل اصلی بسیاری از بیماری هاست."],["The underlying cause of the problem is poverty.","علت اصلی این مشکل فقر است."],["We need to understand the underlying principles.","ما باید اصول اساسی را درک کنیم."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:utilize','utilize','v','استفاده کردن، به کار بردن','/ˈjuːtəlaɪz/ · use','The Romans utilized concrete as a building material.','[["The Romans utilized concrete as a building material.","رومی‌ها از بتن به عنوان مصالح ساختمانی استفاده می‌کردند."]]','awl',6,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:adapt','adapt','v','سازگار شدن، تطبیق دادن','/əˈdæpt/ · adjust, modify','The play is an adaptation of a short novel','[["The play is an adaptation of a short novel","این نمایشنامه اقتباسی از یک رمان کوتاه است"],["Animals adapt to their environment.","حیوانات با محیط خود سازگار می‌شوند."],["Animals must adapt to changes in their environment.","حیوانات باید با تغییرات محیطی سازگار شوند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
