INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:advocate','advocate','n','طرفدار، مدافع؛ حمایت کردن','/ˈædvəkeɪt/ · n., v. · support, back','He was an untiring advocate of economic reform.','[["He was an untiring advocate of economic reform.","او مدافع خستگی ناپذیر اصلاحات اقتصادی بود."],["She advocates for animal rights.","او مدافع حقوق حیوانات است."],["Doctors advocate a diet rich in vegetables.","پزشکان از رژیم غذایی سرشار از سبزیجات حمایت می‌کنند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
