INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:chemical','chemical','n','ماده شیمیایی؛ شیمیایی','/ˈkemɪkl/ · n., adj. · a substance produced by a chemical process','The teacher showed us two kinds of chemical reactions today.','[["The teacher showed us two kinds of chemical reactions today.","معلم امروز دو نوع واکنش شیمیایی را به ما نشان داد."],["Farmers use chemicals to protect their crops.","کشاورزان برای محافظت از محصولات خود از مواد شیمیایی استفاده می‌کنند."],["The factory released dangerous chemicals into the river.","کارخانه مواد شیمیایی خطرناکی را به رودخانه رها کرد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
