INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:empirical','empirical','adj','تجربی','/ɪmˈpɪrɪkəl/ · practical, experimental','They provided empirical evidence to support their argument.','[["They provided empirical evidence to support their argument.","آنها شواهد تجربی برای حمایت از استدلال خود ارائه کردند."],["There is little empirical evidence.","شواهد تجربی کمی وجود دارد."],["The theory is supported by empirical evidence.","این نظریه توسط شواهد تجربی پشتیبانی می‌شود."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
