INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:global','global','adj','جهانی','/ˈɡləʊbl/ · universal, worldwide','There is no obstacle to making our company global.','[["There is no obstacle to making our company global.","هیچ مانعی برای جهانی شدن شرکت ما وجود ندارد."],["Global warming affects every country.","گرمایش زمین هر کشوری را تحت تاثیر قرار می‌دهد."],["Climate change is a global problem.","تغییر اقلیم یک مشکل جهانی است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:grade','grade','n','درجه، رتبه؛ نمره','/ɡreɪd/ · level, rank','You need to improve your grades.','[["You need to improve your grades.","شما باید نمرات خود را ارتقا دهید."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:guarantee','guarantee','n','ضمانت، تضمین','/ˌɡærənˈtiː/ · assurance','They wanted a guarantee that the document was authentic.','[["They wanted a guarantee that the document was authentic.","آنها ضمانت می‌خواستند که سند معتبر باشد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:hierarchy','hierarchy','n','سلسله‌مراتب','/ˈhaɪərɑːrki/ · ranking, grading','the hierarchical structure of medieval society','[["the hierarchical structure of medieval society","ساختار سلسله مراتبی جامعه قرون وسطی"],["Wolves live in a strict hierarchy.","گرگ‌ها در یک سلسله مراتب سخت زندگی می‌کنند."],["There is a strict hierarchy in the army.","یک سلسله مراتب سخت در ارتش وجود دارد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:identical','identical','adj','یکسان، همانند','/aɪˈdentɪkl/ · very similar, equal','The results were identical to those of the first test.','[["The results were identical to those of the first test.","نتایج با نتایج آزمایش اول یکسان بود."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
