INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:infer','infer','v','استنباط کردن، نتیجه گرفتن','/ɪnˈfɜːr/ · deduce, conclude','From these facts we can infer that crime has been increasing.','[["From these facts we can infer that crime has been increasing.","از این حقایق می‌توان نتیجه گرفت که جرم و جنایت در حال افزایش است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:innovative','innovative','adj','نوآورانه، خلاق','/ˈɪnəveɪtɪv/ · creative','technological innovations designed to save energy','[["technological innovations designed to save energy","نوآوری‌های تکنولوژیکی که برای صرفه جویی در انرژی طراحی شده اند"],["The company is known for its innovative products.","این شرکت به خاطر محصولات نوآورانه خود شناخته شده است."],["She came up with an innovative solution.","او با یک راه حل خلاقانه آمد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:insert','insert','v','وارد کردن، داخل کردن','/ɪnˈsɜːrt/ · put into, inject','Insert your credit card here.','[["Insert your credit card here.","کارت اعتباری خود را در اینجا وارد کنید."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:intervene','intervene','v','مداخله کردن، میانجی‌گری کردن','/ˌɪntərˈviːn/ · involve, intercede','We do not need further government intervention.','[["We do not need further government intervention.","ما نیازی به دخالت بیشتر دولت نداریم."],["The government intervened to stop prices rising.","دولت برای جلوگیری از افزایش قیمت‌ها مداخله کرد."],["The teacher intervened in the fight.","معلم در دعوا دخالت کرد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:isolate','isolate','v','جدا کردن، منزوی کردن','/ˈaɪsəleɪt/ · separate','The camp is located in an isolated area.','[["The camp is located in an isolated area.","کمپ در منطقه ای دور افتاده واقع شده است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:media','media','n','رسانه‌ها','/ˈmiːdiə/ · press, mass media','The media are covering the speech tonight.','[["The media are covering the speech tonight.","رسانه‌ها این سخنرانی امشب را پوشش می‌دهند."],["The media has a strong influence on opinion.","رسانه‌ها تاثیر زیادی بر افکار دارند."],["The media play an important role in society.","رسانه‌ها نقش مهمی در جامعه دارند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:mode','mode','n','حالت، شیوه','/məʊd/ · way, method','Cars, buses, and trains are popular modes of transportation.','[["Cars, buses, and trains are popular modes of transportation.","ماشین‌ها، اتوبوس‌ها و قطارها روش‌های محبوب حمل‌ونقل هستند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:paradigm','paradigm','n','الگو، پارادایم','/ˈpærədaɪm/ · example, model, pattern','a new study that challenges the current evolutionary paradigm','[["a new study that challenges the current evolutionary paradigm","مطالعه جدیدی که پارادایم تکاملی کنونی را به چالش می‌کشد"],["The discovery caused a paradigm shift.","این کشف باعث تغییر پارادایم شد."],["The old paradigm of education is changing.","پارادایم قدیمی آموزش در حال تغییر است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:phenomenon','phenomenon','n','پدیده','/fəˈnɑːmɪnən/ · event, happening','natural phenomena like lightning and earthquakes','[["natural phenomena like lightning and earthquakes","پدیده‌های طبیعی مانند رعد و برق و زلزله"],["Globalization is a modern phenomenon.","جهانی شدن یک پدیده مدرن است."],["Northern lights are a natural phenomenon.","شفق شمالی یک پدیده طبیعی است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:priority','priority','n','اولویت','/praɪˈɔːrəti/ · greater importance','Education is a top priority.','[["Education is a top priority.","آموزش در اولویت است."],["Safety is our top priority.","ایمنی اولویت اصلی ماست."],["My family is my top priority.","خانواده من اولویت اصلی من است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:prohibit','prohibit','v','ممنوع کردن، منع کردن','/prəˈhɪbɪt, prəʊˈhɪbɪt/ · ban, forbid','Smoking is prohibited in all areas of the building.','[["Smoking is prohibited in all areas of the building.","استعمال دخانیات در تمامی قسمت‌های ساختمان ممنوع است."],["Smoking is prohibited in public buildings.","سیگار کشیدن در ساختمان‌های عمومی ممنوع است."],["The law prohibits the sale of alcohol to minors.","قانون فروش مشروبات الکلی به افراد زیر سن قانونی را ممنوع کرده است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:publication','publication','n','انتشار، نشریه','/ˌpʌblɪˈkeɪʃn/ · printing','She became famous after the publication of her first novel.','[["She became famous after the publication of her first novel.","او پس از انتشار اولین رمانش به شهرت رسید."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
