INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:release','release','v','آزاد کردن، منتشر کردن','/rɪˈliːs/ · set free, give up','The hostages have been released.','[["The hostages have been released.","گروگان‌ها آزاد شده اند."],["Volcanoes release gases into the air.","آتشفشان‌ها گازهایی را در هوا آزاد می‌کنند."],["The prisoner was released after five years.","این زندانی پس از پنج سال آزاد شد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
