INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:solely','solely','adv','فقط، صرفاً','/ˈsəʊlli/ · only, merely','You will be held solely responsible for any damage.','[["You will be held solely responsible for any damage.","شما تنها مسئول هر گونه خسارت خواهید بود."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
