INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:successive','successive','adj','پیاپی، متوالی','/səkˈsesɪv/ · consecutive, sequential','The team has won three successive championships.','[["The team has won three successive championships.","این تیم سه بار پیاپی قهرمان شده است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:survive','survive','v','زنده ماندن، جان سالم به در بردن','/sərˈvaɪv/ · remain alive, outlive','Just eight passengers survived the plane crash.','[["Just eight passengers survived the plane crash.","تنها هشت مسافر از سقوط هواپیما جان سالم به در بردند."],["Camels can survive without water for days.","شترها می‌توانند روزها بدون آب زنده بمانند."],["Only three people survived the crash.","تنها سه نفر از این تصادف جان سالم به در بردند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:thesis','thesis','n','پایان‌نامه؛ نظریه، تز','/ˈθiːsɪs/ · theory, assumption','Research confirms her thesis that not all women enjoy shopping.','[["Research confirms her thesis that not all women enjoy shopping.","تحقیقات این نظریه را تأیید می‌کند که همه زنان از خرید کردن لذت نمی‌برند."],["She wrote her thesis on Persian poetry.","او پایان نامه خود را در مورد شعر فارسی نوشت."],["The main thesis of the book is simple.","پایان نامه اصلی کتاب ساده است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:topic','topic','n','موضوع','/ˈtɑːpɪk/ · subject, issue','She tried to think of another topic of conversation.','[["She tried to think of another topic of conversation.","سعی کرد به موضوع دیگری برای گفتگو فکر کند."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:transmit','transmit','v','انتقال دادن، فرستادن','/trænzˈmɪt/ · carry, transfer, pass','The equipment is used for the transmission of television signals.','[["The equipment is used for the transmission of television signals.","این تجهیزات برای انتقال سیگنال‌های تلویزیونی استفاده می‌شود."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ultimately','ultimately','adv','سرانجام، در نهایت','/ˈʌltɪmətli/ · in the end','Ultimately, he has only himself to blame.','[["Ultimately, he has only himself to blame.","در نهایت فقط خودش مقصر است."],["Ultimately, the decision is yours.","در نهایت تصمیم با شماست."],["The plan ultimately failed.","این طرح در نهایت شکست خورد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:unique','unique','adj','منحصربه‌فرد، بی‌نظیر','/juˈniːk/ · be the only one of its kind','Each person''s DNA is unique.','[["Each person''s DNA is unique.","DNA هر فرد منحصر به فرد است."],["Every person''s fingerprints are unique.","اثر انگشت هر فردی منحصر به فرد است."],["The island has a unique ecosystem.","این جزیره دارای یک اکوسیستم منحصر به فرد است."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
