INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:voluntary','voluntary','adj','داوطلبانه','/ˈvɑːlənteri/ · of your own free will','She made a voluntary decision to go back to school.','[["She made a voluntary decision to go back to school.","او داوطلبانه تصمیم گرفت که به مدرسه برگردد."]]','awl',7,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:abandon','abandon','v','رها کردن، ترک کردن','/əˈbændən/ · quit, leave, give up','How could she abandon her own child?','[["How could she abandon her own child?","چگونه می‌توانست فرزند خود را رها کند؟"],["They abandoned the old car in the desert.","ماشین قدیمی را در بیابان رها کردند."],["They had to abandon their car in the snow.","آنها مجبور شدند ماشین خود را در برف رها کنند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
