INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ambiguous','ambiguous','adj','مبهم، دوپهلو','/æmˈbɪɡjuəs/ · unclear, obscure','Their position in society remains ambiguous.','[["Their position in society remains ambiguous.","جایگاه آنها در جامعه همچنان مبهم است."],["The question was ambiguous.","سوال مبهم بود."],["The instructions were ambiguous.","دستورالعمل‌ها مبهم بود."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
