INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:arbitrary','arbitrary','adj','دلبخواهی، اختیاری، بی‌قاعده','/ˈɑːrbɪtreri/ · random, casual','He makes unpredictable, arbitrary decisions.','[["He makes unpredictable, arbitrary decisions.","او تصمیمات غیرقابل پیش بینی و خودسرانه می‌گیرد."],["The rules seemed arbitrary.","قوانین خودسرانه به نظر می‌رسید."],["The rules seem completely arbitrary.","قوانین کاملاً دلخواه به نظر می‌رسند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
