INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:conform','conform','v','مطابقت کردن، پیروی کردن','/kənˈfɔːrm/ · v., n. · comply; adjust','The building does not conform with safety regulations.','[["The building does not conform with safety regulations.","ساختمان با مقررات ایمنی مطابقت ندارد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:commodity','commodity','n','کالا','/kəˈmɑːdəti/ · goods, product','Time is a precious commodity.','[["Time is a precious commodity.","زمان یک کالای گرانبها است."],["Water is becoming a valuable commodity.","آب در حال تبدیل شدن به یک کالای ارزشمند است."],["Oil is a valuable commodity.","نفت یک کالای با ارزش است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
