INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:crucial','crucial','adj','بسیار مهم، حیاتی','/ˈkruːʃl/ · vital, critical','Parents play a crucial role in preparing their child for school.','[["Parents play a crucial role in preparing their child for school.","والدین نقش مهمی در آماده سازی فرزندشان برای مدرسه دارند."],["Sleep is crucial for good health.","خواب برای سلامتی بسیار مهم است."],["This is a crucial moment in the game.","این یک لحظه حیاتی در بازی است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
