INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:detect','detect','v','کشف کردن، تشخیص دادن','/dɪˈtekt/ · discover, solve','the public can help the police to detect crime','[["the public can help the police to detect crime","مردم می‌توانند به پلیس برای کشف جرم کمک کنند"]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
