INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:displace','displace','v','جابه‌جا کردن، آواره کردن','/dɪsˈpleɪs/ · replace, shift','The building of a new dam will displace a lot of people.','[["The building of a new dam will displace a lot of people.","ساخت یک سد جدید بسیاری از مردم را آواره خواهد کرد."],["The flood displaced thousands.","سیل هزاران نفر را آواره کرد."],["The war displaced thousands of families.","جنگ هزاران خانواده را آواره کرد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:dramatic','dramatic','adj','چشمگیر، ناگهانی؛ نمایشی','/drəˈmætɪk/ · great and sudden, noticeable','The change in him was dramatic.','[["The change in him was dramatic.","تغییر در او چشمگیر بود."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:eventually','eventually','adv','سرانجام، در نهایت','/ɪˈventʃuəli/ · finally','Did they ever pay you?'' ''Eventually, yes.''','[["Did they ever pay you?'' ''Eventually, yes.''","آیا آنها هرگز به شما پول پرداختند؟ \"در نهایت، بله.\""],["He eventually found a job.","او سرانجام شغلی پیدا کرد."],["After many attempts, he eventually passed the exam.","او پس از تلاش‌های فراوان در نهایت امتحان را پس داد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:exhibit','exhibit','v','نمایش دادن، به نمایش گذاشتن','/ɪɡˈzɪbɪt/ · show','They will be exhibiting a collection of paintings.','[["They will be exhibiting a collection of paintings.","آنها مجموعه ای از نقاشی‌ها را به نمایش خواهند گذاشت."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:exploit','exploit','v','بهره‌برداری کردن؛ استثمار کردن','/ɪkˈsplɔɪt/ · take advantage of, abuse','the exploitation of migrant workers','[["the exploitation of migrant workers","استثمار کارگران مهاجر"],["Some firms exploit cheap labor.","برخی از شرکت‌ها از نیروی کار ارزان بهره برداری می‌کنند."],["Some companies exploit their workers.","برخی از شرکت‌ها از کارگران خود استثمار می‌کنند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:fluctuate','fluctuate','v','نوسان داشتن','/ˈflʌktʃueɪt/ · vary, differ','The price of gold continually fluctuates.','[["The price of gold continually fluctuates.","قیمت طلا به طور مداوم در نوسان است."],["Oil prices fluctuated throughout the year.","قیمت نفت در طول سال در نوسان بود."],["Prices fluctuated wildly during the year.","قیمت‌ها در طول سال به شدت نوسان داشتند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:guideline','guideline','n','رهنمود، دستورالعمل','/ˈɡaɪdlaɪn/ · instruction, direction','This chapter gives you some guidlines to help you.','[["This chapter gives you some guidlines to help you.","این فصل به شما دستورالعمل‌هایی برای کمک به شما می‌دهد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:highlight','highlight','v','برجسته کردن، تأکید کردن','/ˈhaɪlaɪt/ · emphasize, underline','The teacher highlighted the spelling errors by circling each one.','[["The teacher highlighted the spelling errors by circling each one.","معلم با دور هر یک از آنها اشتباهات املایی را برجسته کرد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:implicit','implicit','adj','ضمنی، تلویحی','/ɪmˈplɪsɪt/ · indirect, hidden','Her words contained an implicit threat.','[["Her words contained an implicit threat.","سخنان او حاوی یک تهدید ضمنی بود."],["There was an implicit criticism in his words.","انتقاد تلویحی در سخنان او بود."],["The rules are implicit rather than written.","قوانین به جای نوشته شدن، ضمنی هستند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:induce','induce','v','وادار کردن، القا کردن','/ɪnˈduːs/ · persuade, convince','None of these measures induced a change of policy.','[["None of these measures induced a change of policy.","هیچ یک از این اقدامات باعث تغییر سیاست نشد."],["Some drugs induce sleep.","برخی داروها خواب را تحریک می‌کنند."],["Stress can induce headaches.","استرس می‌تواند باعث سردرد شود."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:inevitably','inevitably','adv','ناگزیر، به‌طور اجتناب‌ناپذیر','/ɪnˈevɪtəbli/ · certainly, surely','War inevitably has casualties.','[["War inevitably has casualties.","جنگ ناگزیر تلفاتی دارد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:infrastructure','infrastructure','n','زیرساخت','/ˈɪnfrəstrʌktʃər/ · basis, foundation','Some countries lack a suitable economic infrastructure.','[["Some countries lack a suitable economic infrastructure.","برخی کشورها فاقد زیرساخت‌های اقتصادی مناسب هستند."],["The country needs better infrastructure.","کشور به زیرساخت‌های بهتری نیاز دارد."],["The country needs to invest in its infrastructure.","این کشور باید در زیرساخت‌های خود سرمایه گذاری کند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:inspect','inspect','v','بازرسی کردن','/ɪnˈspekt/ · examine, investigate','Please have your tickets ready for inspection.','[["Please have your tickets ready for inspection.","لطفا بلیط‌های خود را برای بازرسی آماده کنید."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:intensity','intensity','n','شدت','/ɪnˈtensəti/ · power, force','The intensity of the hurricane was frightening.','[["The intensity of the hurricane was frightening.","شدت طوفان ترسناک بود."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:manipulate','manipulate','v','دستکاری کردن؛ اداره کردن','/məˈnɪpjuleɪt/ · handle, exploit','She knows how to manipulate her parents to get what she wants.','[["She knows how to manipulate her parents to get what she wants.","او می‌داند که چگونه پدر و مادرش را دستکاری کند تا به آنچه می‌خواهد برسد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:minimize','minimize','v','به حداقل رساندن','/ˈmɪnɪmaɪz/ · reduced to the smallest size','The aim is to minimize costs.','[["The aim is to minimize costs.","هدف به حداقل رساندن هزینه‌ها است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
