INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:offset','offset','v','جبران کردن، خنثی کردن','/ˈɒfset/ · balance, compensate for','Higher prices were offset by better quality.','[["Higher prices were offset by better quality.","قیمت‌های بالاتر با کیفیت بهتر جبران شد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:paragraph','paragraph','n','بند، پاراگراف','/ˈpærəɡræf/ · a section of a piece of writing','Please refer to paragraph 4 for the appropriate info.','[["Please refer to paragraph 4 for the appropriate info.","لطفاً برای اطلاعات مناسب به بند 4 مراجعه کنید."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:plus','plus','prep','به‌علاوه، بعلاوه','/plʌs/ · add to','Two plus five is sevsn.','[["Two plus five is sevsn.","دو به علاوه پنج sevsn است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:practitioner','practitioner','n','متخصص شاغل (پزشک یا وکیل)','/prækˈtɪʃənər/ · sb who works as a doctor or lawyer','Patients are treated by skilled practitioners.','[["Patients are treated by skilled practitioners.","بیماران توسط پزشکان ماهر درمان می‌شوند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:predominantly','predominantly','adv','عمدتاً، بیشتر','/prɪˈdɑːmɪnəntli/ · mostly','The people in that neighborhood are predominantly older.','[["The people in that neighborhood are predominantly older.","مردم آن محله عمدتاً مسن‌تر هستند."],["The area is predominantly residential.","این منطقه عمدتاً مسکونی است."],["The town''s population is predominantly young.","جمعیت این شهر عمدتاً جوان هستند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:prospect','prospect','n','چشم‌انداز، احتمال','/ˈprɑːspekt/ · view, future','the frightening prospect of going to war','[["the frightening prospect of going to war","دورنمای ترسناک رفتن به جنگ"],["Graduates face poor job prospects.","فارغ التحصیلان با چشم انداز شغلی ضعیفی روبرو هستند."],["There is little prospect of finding a job here.","دورنمای کمی برای یافتن شغل در اینجا وجود دارد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:radical','radical','adj','بنیادی، ریشه‌ای؛ افراطی','/ˈrædɪkl/ · extreme; fundamental, thorough','The government introduced radical changes to the education system.','[["The government introduced radical changes to the education system.","دولت تغییرات اساسی در نظام آموزشی ایجاد کرد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:random','random','adj','تصادفی','/ˈrændəm/ · by chance','The computer will generate apparently random numbers.','[["The computer will generate apparently random numbers.","کامپیوتر اعداد ظاهرا تصادفی تولید می‌کند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:reinforce','reinforce','v','تقویت کردن','/ˌriːɪnˈfɔːrs/ · strengthen','You should reinforce your argument by giving more facts.','[["You should reinforce your argument by giving more facts.","شما باید استدلال خود را با ارائه حقایق بیشتر تقویت کنید."],["The walls were reinforced with steel.","دیوارها با فولاد تقویت شدند."],["The results reinforce the idea that exercise helps memory.","نتایج این ایده را تقویت می‌کند که ورزش به حافظه کمک می‌کند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:restore','restore','v','بازگرداندن، مرمت کردن','/rɪˈstɔːr/ · bring back, fix','The queen''s wise rule restored peace in the land.','[["The queen''s wise rule restored peace in the land.","حکومت عاقلانه ملکه آرامش را به سرزمین بازگرداند."],["They restored the old palace.","آنها کاخ قدیمی را بازسازی کردند."],["The old palace has been restored.","کاخ قدیمی بازسازی شده است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:revise','revise','v','بازبینی کردن، اصلاح کردن','/rɪˈvaɪz/ · review, reassess','The article, of course, is subject to revision by the editors.','[["The article, of course, is subject to revision by the editors.","البته این مقاله در معرض تجدید نظر ویراستاران است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:schedule','schedule','n','برنامه، جدول زمانی','/ˈskedʒuːl/ · scheme, timetable','I have a hectic schedule for the next few days.','[["I have a hectic schedule for the next few days.","من برای چند روز آینده برنامه پرتنشی دارم."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:tension','tension','n','تنش، فشار عصبی','/ˈtenʃn/ · nervous feeling','Exercise is the ideal way to relieve tension after a hard day.','[["Exercise is the ideal way to relieve tension after a hard day.","ورزش راهی ایده آل برای کاهش تنش پس از یک روز سخت است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:terminate','terminate','v','خاتمه دادن، پایان دادن','/ˈtɜːrmɪneɪt/ · end, complete','You may face a reduction or terminate of benefits.','[["You may face a reduction or terminate of benefits.","ممکن است با کاهش یا خاتمه مزایا مواجه شوید."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:theme','theme','n','مضمون، موضوع اصلی','/θiːm/ · main idea','The book''s theme is the conflict between love and duty.','[["The book''s theme is the conflict between love and duty.","موضوع کتاب تضاد عشق و وظیفه است."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:thereby','thereby','adv','بدین وسیله، در نتیجه','/ˌðerˈbaɪ/ · in consequence of','She studied hard, thereby making sure she was ready for the test.','[["She studied hard, thereby making sure she was ready for the test.","او به سختی مطالعه کرد و در نتیجه مطمئن شد که برای آزمون آماده است."],["He stopped smoking, thereby improving his health.","او سیگار را ترک کرد و در نتیجه سلامت خود را بهبود بخشید."],["Trees absorb carbon, thereby reducing pollution.","درختان کربن را جذب می‌کنند و در نتیجه آلودگی را کاهش می‌دهند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:uniform','uniform','n','یونیفرم؛ یکنواخت','/ˈjuːnɪfɔːrm/ · special clothes worn by a group; the same everywhere','He was on duty and in uniform.','[["He was on duty and in uniform.","او در حال انجام وظیفه و یونیفرم بود."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:vehicle','vehicle','n','وسیله نقلیه، خودرو','/ˈviːəkl/ · motor vehicle, car','A truck driver died last night when his vehicle overturned.','[["A truck driver died last night when his vehicle overturned.","یک راننده کامیون شب گذشته بر اثر واژگونی خودرو جان خود را از دست داد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:via','via','prep','از طریق، به واسطهٔ','/ˈvaɪə, ˈviːə/ · by way of','They came to Europe via Turkey.','[["They came to Europe via Turkey.","آنها از طریق ترکیه به اروپا آمدند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:virtually','virtually','adv','عملاً، تقریباً','/ˈvɜːrtʃuəli/ · practically','We spent virtually all day shopping.','[["We spent virtually all day shopping.","ما تقریبا تمام روز را صرف خرید کردیم."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:widespread','widespread','adj','گسترده، فراگیر','/ˈwaɪdspred/ · common, routine','She enjoyed widespread fame after her new film came out.','[["She enjoyed widespread fame after her new film came out.","او پس از اکران فیلم جدیدش از شهرت گسترده ای برخوردار شد."],["There is widespread support for the plan.","حمایت گسترده ای از این طرح وجود دارد."],["There is widespread concern about the economy.","نگرانی‌های گسترده ای در مورد اقتصاد وجود دارد."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:visual','visual','adj','بصری، دیداری','/ˈvɪʒuəl/ · related to sight','Maps are a visual tool for learning.','[["Maps are a visual tool for learning.","نقشه‌ها یک ابزار بصری برای یادگیری هستند."]]','awl',8,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:accommodation','accommodation','n','محل اقامت','/əˌkɑːməˈdeɪʃn/ · shelter','The price includes flights & accommodation.','[["The price includes flights & accommodation.","قیمت شامل پرواز و اقامت است."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:analogous','analogous','adj','مشابه، قابل قیاس','/əˈnæləɡəs/ · similar, alike','The report''s findings are analogous with our own.','[["The report''s findings are analogous with our own.","یافته‌های این گزارش مشابه یافته‌های ما است."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:anticipate','anticipate','v','پیش‌بینی کردن، انتظار داشتن','/ænˈtɪsɪpeɪt/ · expect, predict','Are you anticipating a lot of people at the party tonight?','[["Are you anticipating a lot of people at the party tonight?","آیا منتظر حضور افراد زیادی در مهمانی امشب هستید؟"],["We anticipate a busy summer.","تابستان شلوغی را پیش بینی می‌کنیم."],["We don''t anticipate any problems with the new system.","ما هیچ مشکلی با سیستم جدید پیش بینی نمی‌کنیم."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:assurance','assurance','n','اطمینان، تضمین','/əˈʃʊrəns/ · confidence, promise','He spoke with quiet assurance about his future plans.','[["He spoke with quiet assurance about his future plans.","او با اطمینان آرام در مورد برنامه‌های آینده خود صحبت کرد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:attain','attain','v','دست یافتن، رسیدن به','/əˈteɪn/ · succeed in doing sth, accomplish','He has attained the highest grade in his music exams.','[["He has attained the highest grade in his music exams.","او بالاترین نمره را در امتحانات موسیقی خود کسب کرده است."],["Few students attain a perfect score.","تعداد کمی از دانش آموزان به نمره کامل می‌رسند."],["She attained the highest score in the class.","او بالاترین نمره را در کلاس کسب کرد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:behalf','behalf','n','از طرف، به نمایندگی از','/bɪˈhæf/ · as a representative','She asked the doctor to speak to her parents on her behalf.','[["She asked the doctor to speak to her parents on her behalf.","او از دکتر خواست تا از طرف او با والدینش صحبت کند."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:bulk','bulk','n','حجم، بخش عمده','/bʌlk/ · the main part','We spent the bulk of the summer at the beach.','[["We spent the bulk of the summer at the beach.","ما بیشتر تابستان را در ساحل گذراندیم."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:cease','cease','v','متوقف کردن، دست کشیدن','/siːs/ · stop','The factory ceased operations last year.','[["The factory ceased operations last year.","این کارخانه سال گذشته فعالیت خود را متوقف کرد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:coherence','coherence','n','انسجام، پیوستگی','/kəʊˈhɪrəns/ · consistency','There was no coherence between the 1st and the 2nd half of the film.','[["There was no coherence between the 1st and the 2nd half of the film.","هیچ انسجامی بین نیمه اول و دوم فیلم وجود نداشت."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:coincide','coincide','v','همزمان شدن، مصادف شدن','/ˌkəʊɪnˈsaɪd/ · happen at the same time','The goals of the business partners coincide.','[["The goals of the business partners coincide.","اهداف شرکای تجاری منطبق است."],["The festival coincides with the harvest.","جشنواره همزمان با برداشت محصول است."],["My birthday coincides with the holiday this year.","تولد من مصادف با تعطیلات امسال است."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:commence','commence','v','آغاز کردن، شروع شدن','/kəˈmens/ · start','Shall we let the meeting commence, gentlemen?','[["Shall we let the meeting commence, gentlemen?","آقایان اجازه بدهیم جلسه شروع شود؟"]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:incompatible','incompatible','adj','ناسازگار','/ˌɪnkəmˈpætəbl/ · mismatched, opposite','I don''t know why they ever got married. They''re totally incompatible.','[["I don''t know why they ever got married. They''re totally incompatible.","من نمی‌دانم چرا آنها هرگز ازدواج کردند. آنها کاملاً ناسازگار هستند."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:concurrent','concurrent','adj','همزمان','/kənˈkɜːrənt/ · occurring at the same time','The exhibition reflected concurrent developments abroad.','[["The exhibition reflected concurrent developments abroad.","این نمایشگاه منعکس کننده تحولات همزمان در خارج از کشور بود."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:confine','confine','v','محدود کردن، محصور کردن','/kənˈfaɪn/ · restrict','It wasn''t easy to sleep in such a confined space.','[["It wasn''t easy to sleep in such a confined space.","خوابیدن در چنین فضای محدودی آسان نبود."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:controversy','controversy','n','جدل، مناقشه','/ˈkɑːntrəvɜːrsi/ · dispute, debate','The judges'' decision provoked controversy.','[["The judges'' decision provoked controversy.","تصمیم داوران جنجال برانگیخت."],["The decision caused controversy.","این تصمیم جنجال به پا کرد."],["There is controversy over the use of animals in research.","در مورد استفاده از حیوانات در تحقیقات اختلاف نظر وجود دارد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:conversely','conversely','adv','برعکس، در مقابل','/ˈkɑːnvɜːrsli/ · contrary, vice versa','We prefer white eggs; conversely, British buyers like brown eggs.','[["We prefer white eggs; conversely, British buyers like brown eggs.","ما تخم مرغ سفید را ترجیح می‌دهیم. برعکس، خریداران بریتانیایی تخم مرغ قهوه ای را دوست دارند."],["Conversely, rural areas saw a decline.","برعکس، مناطق روستایی کاهش یافت."],["Some people love city life; conversely, others prefer the countryside.","برخی از مردم زندگی شهری را دوست دارند. برعکس، دیگران روستا را ترجیح می‌دهند."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:device','device','n','دستگاه، وسیله','/dɪˈvaɪs/ · tool','a device for separating metal from garbage.','[["a device for separating metal from garbage.","وسیله ای برای جدا کردن فلز از زباله"]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:devoted','devoted','adj','فداکار، وفادار، مخلص','/dɪˈvəʊtɪd/ · committed, faithful, loyal','Lucy is devoted to her cats.','[["Lucy is devoted to her cats.","لوسی به گربه هایش اختصاص دارد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:diminish','diminish','v','کاهش یافتن، کم کردن','/dɪˈmɪnɪʃ/ · reduce, decline','a diminished role for local government','[["a diminished role for local government","کاهش نقش دولت محلی"],["The pain diminished after an hour.","درد بعد از یک ساعت کاهش یافت."],["The pain gradually diminished.","درد به تدریج کاهش یافت."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:distort','distort','v','تحریف کردن','/dɪˈstɔːrt/ · deform, misrepresent','The virus causes distortion of the leaves.','[["The virus causes distortion of the leaves.","این ویروس باعث انحراف برگها می‌شود."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:duration','duration','n','مدت، طول زمان','/duˈreɪʃn/ · length of time','The course is of three years'' duration.','[["The course is of three years'' duration.","دوره به مدت سه سال می‌باشد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:erode','erode','v','فرسایش یافتن، فرسودن','/ɪˈrəʊd/ · wear away, rot','the gradual erosion of our civil liberties','[["the gradual erosion of our civil liberties","فرسایش تدریجی آزادی‌های مدنی ما"],["Waves eroded the cliffs.","امواج صخره‌ها را فرسایش دادند."],["Wind and rain have eroded the cliffs.","باد و باران صخره‌ها را فرسایش داده است."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ethical','ethical','adj','اخلاقی','/ˈeθɪkl/ · moral, proper','Some doctors feel that this procedure is not medically ethical.','[["Some doctors feel that this procedure is not medically ethical.","برخی از پزشکان معتقدند که این روش از نظر پزشکی اخلاقی نیست."],["Animal testing raises ethical questions.","آزمایش بر روی حیوانات سوالات اخلاقی را مطرح می‌کند."],["The company follows strict ethical standards.","این شرکت از استانداردهای اخلاقی سختگیرانه پیروی می‌کند."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:format','format','n','قالب، فرمت','/ˈfɔːrmæt/ · design, form','The courses were run to a consistent format.','[["The courses were run to a consistent format.","دوره‌ها در قالب یکنواخت برگزار شد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:found','found','v','بنیان نهادن، تأسیس کردن','/faʊnd/ · establish, build','The castle is established on solid rock.','[["The castle is established on solid rock.","این قلعه بر روی صخره ای محکم بنا شده است."],["The university was founded in 1934.","این دانشگاه در سال 1934 تاسیس شد."],["The city was founded by traders.","این شهر توسط بازرگانان تأسیس شد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:inherent','inherent','adj','ذاتی، درونی','/ɪnˈherənt/ · intrinsic, innate','Every business has its own inherent risks.','[["Every business has its own inherent risks.","هر کسب و کاری خطرات ذاتی خود را دارد."],["There are risks inherent in any business.","خطرات ذاتی در هر کسب و کاری وجود دارد."],["There are risks inherent in every investment.","در هر سرمایه گذاری ریسک‌هایی وجود دارد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:insight','insight','n','بینش، بصیرت','/ˈɪnsaɪt/ · awareness, perception','There are many valuable insights in her book.','[["There are many valuable insights in her book.","بینش‌های ارزشمند زیادی در کتاب او وجود دارد."],["The study gives new insight into animal behavior.","این مطالعه بینش جدیدی از رفتار حیوانات می‌دهد."],["Her book offers valuable insights into Persian culture.","کتاب او بینش‌های ارزشمندی از فرهنگ ایرانی ارائه می‌دهد."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:integral','integral','adj','جدایی‌ناپذیر، ضروری','/ˈɪntɪɡrəl, ɪnˈteɡrəl/ · vital, essential','Games are an integral part of the school''s curriculum.','[["Games are an integral part of the school''s curriculum.","بازی بخشی جدایی ناپذیر از برنامه درسی مدرسه است."],["Sport is an integral part of school life.","ورزش بخشی جدایی ناپذیر از زندگی مدرسه است."],["Exercise is an integral part of a healthy lifestyle.","ورزش جزء لاینفک یک سبک زندگی سالم است."]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:intermediate','intermediate','adj','متوسط، میانی','/ˌɪntərˈmiːdiət/ · middle, midway','intermediate learners of English','[["intermediate learners of English","زبان آموزان متوسط انگلیسی"]]','awl',9,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
