INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:adjacent','adjacent','adj','مجاور، همسایه','/əˈdʒeɪsnt/ · near or close to','They lived in a house adjacent to the railway.','[["They lived in a house adjacent to the railway.","آنها در خانه ای در مجاورت راه آهن زندگی می‌کردند."],["The lab is adjacent to the library.","آزمایشگاه در مجاورت کتابخانه قرار دارد."],["They live in adjacent apartments.","آنها در آپارتمان‌های مجاور زندگی می‌کنند."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
