INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:integrity','integrity','n','صداقت، درستکاری؛ یکپارچگی','/ɪnˈteɡrəti/ · honesty, unity','She behaved with absolute integrity.','[["She behaved with absolute integrity.","او با صداقت مطلق رفتار کرد."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:intrinsic','intrinsic','adj','ذاتی، درونی','/ɪnˈtrɪnzɪk/ · innate','Flexibility is intrinsic to creative management.','[["Flexibility is intrinsic to creative management.","انعطاف پذیری ذاتی مدیریت خلاق است."],["The painting has little intrinsic value.","این نقاشی ارزش ذاتی کمی دارد."],["Curiosity is an intrinsic part of learning.","کنجکاوی بخشی ذاتی یادگیری است."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:invoke','invoke','v','استناد کردن به؛ برانگیختن','/ɪnˈvəʊk/ · implement, evoke','The UN threatened to invoke economic sanctions.','[["The UN threatened to invoke economic sanctions.","سازمان ملل تهدید به اعمال تحریم‌های اقتصادی کرد."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
