INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:likewise','likewise','adv','همچنین، به همین ترتیب','/ˈlaɪkwaɪz/ · similar','The fish was delicious. Likewise, the eggplant was excellent.','[["The fish was delicious. Likewise, the eggplant was excellent.","ماهی خوشمزه بود بادمجان هم عالی بود."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:nonetheless','nonetheless','adv','با این حال، با وجود این','/ˌnʌnðəˈles/ · however','The paintings are complex, but have plenty of appeal nonetheless.','[["The paintings are complex, but have plenty of appeal nonetheless.","نقاشی‌ها پیچیده هستند، اما با این وجود جذابیت زیادی دارند."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:notwithstanding','notwithstanding','prep','با وجود، علی‌رغم','/ˌnɑːtwɪθˈstændɪŋ/ · in spite of','Notwithstanding his parents objections; he left of the house.','[["Notwithstanding his parents objections; he left of the house.","با وجود مخالفت والدینش؛ او از خانه خارج شد"],["Notwithstanding the costs, the project continued.","با وجود هزینه‌ها، پروژه ادامه یافت."],["Notwithstanding the bad weather, the event was a success.","با وجود آب و هوای بد، این رویداد موفقیت آمیز بود."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
