INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:ongoing','ongoing','adj','جاری، در جریان','/ˈɑːnɡəʊɪŋ/ · continuous','The negotiations are still ongoing.','[["The negotiations are still ongoing.","مذاکرات همچنان ادامه دارد."],["Research into the disease is ongoing.","تحقیقات در مورد این بیماری ادامه دارد."],["There is an ongoing debate about the issue.","بحث در مورد این موضوع ادامه دارد."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:panel','panel','n','هیئت، پنل؛ صفحه','/ˈpænl/ · a board; a group of experts','The roof is covered with solar panels that absorb the sun''s rays.','[["The roof is covered with solar panels that absorb the sun''s rays.","سقف با پنل‌های خورشیدی پوشیده شده است که اشعه‌های خورشید را جذب می‌کند."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:persistent','persistent','adj','سرسخت، مداوم','/pərˈsɪstənt/ · continuing, determined','Persistent reports of human rights abuses by the military','[["Persistent reports of human rights abuses by the military","گزارش‌های مداوم از نقض حقوق بشر توسط ارتش"],["He has a persistent cough.","سرفه مداوم دارد."],["Persistent rain caused flooding.","بارش مداوم باران باعث جاری شدن سیل شد."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:pose','pose','v','ایجاد کردن (مشکل)، مطرح کردن','/pəʊz/ · cause, create','Pollution poses a threat to health.','[["Pollution poses a threat to health.","آلودگی سلامتی را تهدید می‌کند."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:reluctant','reluctant','adj','بی‌میل، اکراه‌دار','/rɪˈlʌktənt/ · unwilling','She seemed reluctant to answer.','[["She seemed reluctant to answer.","به نظر می‌رسید که او تمایلی به پاسخ دادن ندارد."],["She was reluctant to lend him money.","او تمایلی به قرض دادن به او نداشت."],["Many people are reluctant to change their habits.","بسیاری از افراد تمایلی به تغییر عادات خود ندارند."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:so-called','so-called','adj','به‌اصطلاح','/ˌsəʊ ˈkɔːld/ · supposed','The so-called manager had no idea how to manage.','[["The so-called manager had no idea how to manage.","به اصطلاح مدیر هیچ ایده ای برای مدیریت نداشت."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
