INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('awl:undergo','undergo','v','متحمل شدن، تحت (چیزی) قرار گرفتن','/ˌʌndərˈɡəʊ/ · experience, encounter','My mother underwent major surgery last year.','[["My mother underwent major surgery last year.","مادرم پارسال تحت عمل جراحی بزرگ قرار گرفت."],["The city has undergone major changes.","این شهر دستخوش تغییرات اساسی شده است."],["The city is undergoing major changes.","این شهر دستخوش تغییرات اساسی است."]]','awl',10,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
