INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:genius','genius','n','نبوغ، استعداد فوق‌العاده','≈ brilliance, talent — Cambridge 9 · Test 1 · Passage 1: William Henry Perkin','Perkin''s genius led to major industrial progress.','[["Perkin''s genius led to major industrial progress.","نبوغ پرکین منجر به پیشرفت صنعتی عمده شد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
