INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:manufacture','manufacture','v','تولید کردن','≈ produce, fabricate — Cambridge 9 · Test 1 · Passage 1: William Henry Perkin | Cambridge 13 · Test 3 · Passage 3: Glass Innovation','The company began to manufacture synthetic fabrics.','[["The company began to manufacture synthetic fabrics.","این شرکت شروع به تولید پارچه‌های مصنوعی کرد."],["Factories manufacture various types of glass.","کارخانه‌ها انواع مختلفی از شیشه را تولید می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:commercialize','commercialize','v','تجاری‌سازی کردن','≈ market, industrialize — Cambridge 9 · Test 1 · Passage 1: William Henry Perkin','His discovery was quickly commercialized.','[["His discovery was quickly commercialized.","کشف او به سرعت تجاری شد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:patent','patent','n','حق ثبت اختراع','≈ legal right, copyright — Cambridge 9 · Test 1 · Passage 1: William Henry Perkin | Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell','He received a patent for his chemical invention.','[["He received a patent for his chemical invention.","او حق اختراع شیمیایی خود را دریافت کرد."],["He filed a patent for his telephone design.","او یک پتنت برای طراحی تلفن خود به ثبت رساند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
