INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:astronomy','astronomy','n','علم نجوم','≈ space science — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','Astronomy helps us understand the origins of the universe.','[["Astronomy helps us understand the origins of the universe.","ستاره شناسی به ما کمک می‌کند تا منشأ جهان را درک کنیم."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:universe','universe','n','جهان هستی','≈ cosmos, space — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','Scientists study the universe to find signs of life.','[["Scientists study the universe to find signs of life.","دانشمندان جهان را برای یافتن نشانه‌هایی از حیات مطالعه می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:evolve','evolve','v','تکامل یافتن','≈ develop, change gradually — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','Life on Earth evolved over billions of years.','[["Life on Earth evolved over billions of years.","حیات روی زمین طی میلیاردها سال تکامل یافته است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:civilization','civilization','n','تمدن','≈ society, culture — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','Advanced civilizations may exist beyond Earth.','[["Advanced civilizations may exist beyond Earth.","تمدن‌های پیشرفته ممکن است فراتر از زمین وجود داشته باشند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:detect','detect','v','کشف یا شناسایی کردن','≈ discover, identify — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 9 · Test 2 · Passage 1: Hearing Impairment','Telescopes are used to detect distant planets.','[["Telescopes are used to detect distant planets.","از تلسکوپ‌ها برای تشخیص سیارات دور استفاده می‌شود."],["Early screening detects hearing loss in newborns.","غربالگری زودهنگام کاهش شنوایی در نوزادان را تشخیص می‌دهد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:signal','signal','n','علامت، پیام','≈ message, transmission — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','No radio signal has been detected from other galaxies.','[["No radio signal has been detected from other galaxies.","هیچ سیگنال رادیویی از کهکشان‌های دیگر شناسایی نشده است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
