INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:vast','vast','adj','وسیع، عظیم','≈ immense, enormous — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','The universe is vast beyond human imagination.','[["The universe is vast beyond human imagination.","جهان هستی فراتر از تصور انسان است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:assume','assume','v','فرض کردن','≈ suppose, presume — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','Scientists assume that life could form elsewhere.','[["Scientists assume that life could form elsewhere.","دانشمندان تصور می‌کنند که حیات می‌تواند در جای دیگری شکل بگیرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:evidence','evidence','n','شواهد','≈ proof, indication — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There?','There is little evidence for intelligent life beyond Earth.','[["There is little evidence for intelligent life beyond Earth.","شواهد کمی برای حیات هوشمند فراتر از زمین وجود دارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:exploration','exploration','n','اکتشاف','≈ investigation, discovery — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 14 · Test 1 · Passage 1: The Role of Play in Child Development','Space exploration requires huge investment.','[["Space exploration requires huge investment.","اکتشاف فضایی نیاز به سرمایه گذاری هنگفت دارد."],["Exploration enhances creativity and curiosity.","کاوش باعث افزایش خلاقیت و کنجکاوی می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:transmit','transmit','v','ارسال کردن (سیگنال)','≈ send, broadcast — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph | Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell','Data was transmitted back to Earth.','[["Data was transmitted back to Earth.","داده‌ها به زمین بازگردانده شد."],["Messages were transmitted across long distances by telegraph.","پیام‌ها در فواصل طولانی از طریق تلگراف مخابره می‌شد."],["The device could transmit human voice electrically.","این دستگاه می‌تواند صدای انسان را به صورت الکتریکی منتقل کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:colony','colony','n','مستعمره / سکونتگاه فضایی','≈ settlement, outpost — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 12 · Test 2 · Passage 1: The Intelligence of Ants','Humans may one day build colonies on Mars.','[["Humans may one day build colonies on Mars.","انسان‌ها ممکن است روزی در مریخ مستعمرات بسازند."],["Ant colonies function as highly organized societies.","مستعمرات مورچه‌ها به عنوان جوامع بسیار سازمان یافته عمل می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:orbit','orbit','v','مدار / در مدار چرخیدن','v., n. · ≈ circle, revolve around — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 16 · Test 4 · Passage 1: Space Exploration & Astronomy','The satellite orbits the Earth every 90 minutes.','[["The satellite orbits the Earth every 90 minutes.","این ماهواره هر 90 دقیقه به دور زمین می‌چرخد."],["The satellite remains in Earth''s orbit.","این ماهواره در مدار زمین باقی می‌ماند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:telescope','telescope','n','تلسکوپ','≈ optical instrument — Cambridge 9 · Test 1 · Passage 2: Is There Anybody Out There? | Cambridge 16 · Test 4 · Passage 1: Space Exploration & Astronomy','The Hubble telescope has provided detailed images of space.','[["The Hubble telescope has provided detailed images of space.","تلسکوپ هابل تصاویر دقیقی از فضا ارائه کرده است."],["Modern telescopes can capture distant starlight.","تلسکوپ‌های مدرن می‌توانند نور ستارگان دوردست را ثبت کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:intelligence','intelligence','n','هوش','≈ mental ability, intellect — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing','Intelligence is influenced by both genes and environment.','[["Intelligence is influenced by both genes and environment.","هوش هم تحت تأثیر ژن‌ها و هم محیط است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:cognitive','cognitive','adj','شناختی، ذهنی','≈ mental, intellectual — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing | Cambridge 9 · Test 3 · Passage 2: The Psychology of Music | Cambridge 11 · Test 2 · Passage 3: Animal Communication & Language Evolution','Children show rapid cognitive development in early years.','[["Children show rapid cognitive development in early years.","کودکان در سال‌های اولیه رشد شناختی سریعی از خود نشان می‌دهند."],["Listening to music enhances cognitive performance.","گوش دادن به موسیقی عملکرد شناختی را افزایش می‌دهد."],["Cognitive complexity supports language development.","پیچیدگی شناختی از رشد زبان پشتیبانی می‌کند."],["Cognitive skills develop through play and exploration.","مهارت‌های شناختی از طریق بازی و اکتشاف رشد می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:assess','assess','v','ارزیابی کردن','≈ evaluate, measure — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing','Teachers assess students'' abilities using various tests.','[["Teachers assess students'' abilities using various tests.","معلمان با استفاده از آزمون‌های مختلف توانایی‌های دانش آموزان را ارزیابی می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
