INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:achievement','achievement','n','دستاورد','≈ accomplishment, success — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing | Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education','Academic achievement depends on multiple factors.','[["Academic achievement depends on multiple factors.","پیشرفت تحصیلی به عوامل متعددی بستگی دارد."],["High achievement often leads to unrealistic expectations.","موفقیت بالا اغلب منجر به انتظارات غیر واقعی می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:potential','potential','n','توانایی بالقوه','n., adj. · ≈ capability, possibility — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing | Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education','Some children show great academic potential.','[["Some children show great academic potential.","برخی از کودکان پتانسیل تحصیلی بالایی از خود نشان می‌دهند."],["Teachers must recognize students'' potential early.","معلمان باید پتانسیل دانش آموزان را زودتر بشناسند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:evaluate','evaluate','v','ارزیابی کردن','≈ assess, appraise — Cambridge 9 · Test 1 · Passage 3: Intelligence Testing | Cambridge 9 · Test 2 · Passage 2: The Nature of History | Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education','Psychologists evaluate the effectiveness of new intelligence models.','[["Psychologists evaluate the effectiveness of new intelligence models.","روانشناسان اثربخشی مدل‌های هوشی جدید را ارزیابی می‌کنند."],["Scholars evaluate multiple sources before drawing conclusions.","محققان قبل از نتیجه گیری منابع متعدد را ارزیابی می‌کنند."],["Teachers evaluate progress through regular assessments.","معلمان پیشرفت را از طریق ارزیابی‌های منظم ارزیابی می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
