INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:stimulus','stimulus','n','محرک','≈ incentive, trigger — Cambridge 9 · Test 2 · Passage 1: Hearing Impairment | Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At? | Cambridge 11 · Test 1 · Passage 3: Neuroeconomics','Visual stimulus helps hearing-impaired children learn words.','[["Visual stimulus helps hearing-impaired children learn words.","محرک بینایی به کودکان کم شنوا کمک می‌کند تا کلمات را یاد بگیرند."],["Laughter often occurs in response to a social stimulus.","خنده اغلب در پاسخ به یک محرک اجتماعی رخ می‌دهد."],["Visual stimulus affects how people value outcomes.","محرک بصری بر چگونگی ارزش گذاری افراد برای نتایج تأثیر می‌گذارد."],["Temperature acts as a migration stimulus.","دما به عنوان یک محرک مهاجرت عمل می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
