INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:specialist','specialist','n','متخصص','≈ expert, professional — Cambridge 9 · Test 2 · Passage 1: Hearing Impairment | Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting','A speech specialist evaluated the child''s progress.','[["A speech specialist evaluated the child''s progress.","یک متخصص گفتار پیشرفت کودک را ارزیابی کرد."],["A coin specialist values historical rarity.","یک متخصص سکه برای نادر بودن تاریخی ارزش قائل است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
