INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:authenticity','authenticity','n','اصالت','≈ genuineness, validity — Cambridge 9 · Test 2 · Passage 2: The Nature of History | Cambridge 15 · Test 1 · Passage 1: Holiday Tourism & Economic Development | Cambridge 15 · Test 4 · Passage 1: Cultural Heritage & Historical Conservation','The museum verified the authenticity of the artifact.','[["The museum verified the authenticity of the artifact.","موزه اصالت این اثر را تأیید کرد."],["Travelers often seek cultural authenticity in their trips.","مسافران اغلب در سفرهای خود به دنبال اصالت فرهنگی هستند."],["Authenticity is vital for cultural preservation.","اصالت برای حفظ فرهنگ حیاتی است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:bias','bias','n','تعصب، جانب داری','≈ prejudice, partiality — Cambridge 9 · Test 2 · Passage 2: The Nature of History | Cambridge 11 · Test 3 · Passage 3: Risk Perception | Cambridge 12 · Test 1 · Passage 3: Neuroaesthetics','Historians must recognize their own bias.','[["Historians must recognize their own bias.","مورخان باید تعصب خود را بشناسند."],["Cognitive bias affects how risks are evaluated.","سوگیری شناختی بر نحوه ارزیابی ریسک‌ها تأثیر می‌گذارد."],["Cultural bias influences artistic taste.","تعصب فرهنگی بر ذائقه هنری تأثیر می‌گذارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:context','context','n','بستر، زمینه','≈ background, setting — Cambridge 9 · Test 2 · Passage 2: The Nature of History','The letter must be read in its historical context.','[["The letter must be read in its historical context.","نامه را باید در بافت تاریخی آن خواند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:acquisition','acquisition','n','جمع آوری، کسب','≈ collection, attainment — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby','The acquisition of rare stamps became his passion.','[["The acquisition of rare stamps became his passion.","دستیابی به تمبرهای کمیاب به علاقه او تبدیل شد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:motivation','motivation','n','انگیزه','≈ drive, incentive — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby | Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education | Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting','Curiosity is the main motivation behind collecting.','[["Curiosity is the main motivation behind collecting.","کنجکاوی انگیزه اصلی جمع آوری است."],["Internal motivation helps gifted children succeed.","انگیزه درونی به کودکان با استعداد کمک می‌کند تا موفق شوند."],["Motivation for collecting can be emotional.","انگیزه برای جمع آوری می‌تواند احساسی باشد."],["Motivation directly affects workplace performance.","انگیزه مستقیماً بر عملکرد محل کار تأثیر می‌گذارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:compulsion','compulsion','n','اجبار ذهنی','≈ urge, obsession — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby | Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting','For some, collecting becomes a psychological compulsion.','[["For some, collecting becomes a psychological compulsion.","برای برخی، جمع آوری به یک اجبار روانی تبدیل می‌شود."],["Some collectors act out of compulsion.","برخی از کلکسیونرها از روی اجبار عمل می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:prestige','prestige','n','اعتبار، وجهه','≈ status, reputation — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby | Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting | Cambridge 12 · Test 2 · Passage 3: Global English','Owning unique items gives collectors prestige.','[["Owning unique items gives collectors prestige.","داشتن اقلام منحصر به فرد به کلکسیونرها اعتبار می‌بخشد."],["Rare collections bring social prestige.","مجموعه‌های کمیاب اعتبار اجتماعی به ارمغان می‌آورد."],["Speaking English gives prestige in some societies.","صحبت کردن به زبان انگلیسی در برخی جوامع اعتبار می‌بخشد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:satisfaction','satisfaction','n','رضایت','≈ fulfilment, contentment — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby | Cambridge 14 · Test 1 · Passage 3: Workplace Motivation & Productivity','The greatest satisfaction comes from finding a missing piece.','[["The greatest satisfaction comes from finding a missing piece.","بزرگترین رضایت از یافتن یک قطعه گم شده حاصل می‌شود."],["Job satisfaction improves performance retention.","رضایت شغلی حفظ عملکرد را بهبود می‌بخشد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:dedication','dedication','n','تعهد، پشتکار','≈ commitment, devotion — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby','Success in collecting requires dedication and patience.','[["Success in collecting requires dedication and patience.","موفقیت در جمع آوری نیاز به فداکاری و صبر دارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:pursue','pursue','v','دنبال کردن','≈ seek, chase — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby','People pursue hobbies to express creativity.','[["People pursue hobbies to express creativity.","افراد سرگرمی‌هایی را برای ابراز خلاقیت دنبال می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:investment','investment','n','سرمایه‌گذاری','≈ financial input — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby','Some treat collecting as a long-term investment.','[["Some treat collecting as a long-term investment.","برخی جمع آوری را یک سرمایه گذاری بلندمدت می‌دانند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:valuable','valuable','adj','باارزش','≈ precious, costly — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby','The gallery displayed several valuable collections.','[["The gallery displayed several valuable collections.","گالری چندین مجموعه ارزشمند را به نمایش گذاشت."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:exhibit','exhibit','v','به نمایش گذاشتن','≈ display, show — Cambridge 9 · Test 2 · Passage 3: Collecting as a Hobby | Cambridge 10 · Test 3 · Passage 1: The Value of Museums','Museums exhibit objects of cultural significance.','[["Museums exhibit objects of cultural significance.","موزه‌ها اشیاء با اهمیت فرهنگی را به نمایش می‌گذارند."],["The gallery will exhibit rare paintings this year.","این گالری امسال نقاشی‌های کمیاب را به نمایش می‌گذارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:invention','invention','n','اختراع','≈ creation, innovation — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph | Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping','The telegraph was one of the greatest inventions of the 19th century.','[["The telegraph was one of the greatest inventions of the 19th century.","تلگراف یکی از بزرگترین اختراعات قرن نوزدهم بود."],["The invention of the chronometer revolutionized travel.","اختراع کرنومتر انقلابی در سفر ایجاد کرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:pioneer','pioneer','n','پیشگام','≈ trailblazer, innovator — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph | Cambridge 13 · Test 1 · Passage 3: The Art of Photography','Samuel Morse was a pioneer of modern communication.','[["Samuel Morse was a pioneer of modern communication.","ساموئل مورس از پیشگامان ارتباطات مدرن بود."],["He was a pioneer of Canadian photography.","او از پیشگامان عکاسی کانادا بود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:network','network','n','شبکه','≈ system, web — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph','A global telegraph network connected continents.','[["A global telegraph network connected continents.","یک شبکه جهانی تلگراف، قاره‌ها را به هم متصل می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:instantaneous','instantaneous','adj','آنی، فوری','≈ immediate, prompt — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph','Telegraph messages were almost instantaneous compared to letters.','[["Telegraph messages were almost instantaneous compared to letters.","پیام‌های تلگراف در مقایسه با نامه‌ها تقریباً آنی بودند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:innovation','innovation','n','نوآوری','≈ creativity, improvement — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph | Cambridge 10 · Test 2 · Passage 2: The Construction of the Sydney Opera House | Cambridge 13 · Test 1 · Passage 3: The Art of Photography','Innovation in communication reshaped global trade.','[["Innovation in communication reshaped global trade.","نوآوری در ارتباطات تجارت جهانی را تغییر داد."],["Innovation in materials made the project possible.","نوآوری در مواد این پروژه را ممکن کرد."],["Innovation in equipment changed photography.","نوآوری در تجهیزات عکاسی را تغییر داد."],["Innovation led to lighter, stronger glass.","نوآوری منجر به شیشه سبک‌تر و قوی‌تر شد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:distribute','distribute','v','پخش کردن','≈ deliver, allocate — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph','Telegraph offices distributed messages to major cities.','[["Telegraph offices distributed messages to major cities.","دفاتر تلگراف پیام‌ها را به شهرهای بزرگ توزیع می‌کردند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:expansion','expansion','n','گسترش','≈ growth, extension — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph','The expansion of telegraph lines connected remote regions.','[["The expansion of telegraph lines connected remote regions.","گسترش خطوط تلگراف مناطق دورافتاده را به هم متصل می‌کرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:efficient','efficient','adj','کارآمد','≈ effective, productive — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph','The telegraph made communication faster and more efficient.','[["The telegraph made communication faster and more efficient.","تلگراف ارتباط را سریعتر و کارآمدتر کرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:revolutionize','revolutionize','v','متحول کردن','≈ transform, modernize — Cambridge 9 · Test 3 · Passage 1: The History of the Telegraph | Cambridge 11 · Test 3 · Passage 2: Einstein''s Theory of Relativity','The invention revolutionized long- distance communication.','[["The invention revolutionized long- distance communication.","این اختراع ارتباطات راه دور را متحول کرد."],["Einstein''s ideas revolutionized modern physics.","ایده‌های اینشتین فیزیک مدرن را متحول کرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:harmony','harmony','n','هارمونی، هماهنگی','≈ melody, balance — Cambridge 9 · Test 3 · Passage 2: The Psychology of Music | Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture | Cambridge 12 · Test 4 · Passage 2: The Psychology of Music','Harmony creates emotional balance in music.','[["Harmony creates emotional balance in music.","هارمونی باعث ایجاد تعادل عاطفی در موسیقی می‌شود."],["Aboriginal culture emphasizes living in harmony with nature.","فرهنگ بومی بر زندگی در هماهنگی با طبیعت تاکید دارد."],["Musical harmony evokes a sense of peace.","هارمونی موسیقی حس آرامش را برمی انگیزد."],["Harmony evokes emotional stability.","هارمونی ثبات عاطفی را برمی انگیزد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:perception','perception','n','درک، برداشت','≈ awareness, interpretation — Cambridge 9 · Test 3 · Passage 2: The Psychology of Music | Cambridge 11 · Test 3 · Passage 3: Risk Perception | Cambridge 12 · Test 1 · Passage 3: Neuroaesthetics','Musical perception differs among individuals.','[["Musical perception differs among individuals.","درک موسیقی در بین افراد متفاوت است."],["Public perception of risk differs from actual statistics.","درک عمومی از ریسک با آمار واقعی متفاوت است."],["Cultural background shapes perception of beauty.","پس زمینه فرهنگی ادراک زیبایی را شکل می‌دهد."],["Perception determines how we interpret images.","ادراک نحوه تفسیر تصاویر را تعیین می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:stimulate','stimulate','v','تحریک کردن','≈ arouse, encourage — Cambridge 9 · Test 3 · Passage 2: The Psychology of Music','Music can stimulate memory and emotions.','[["Music can stimulate memory and emotions.","موسیقی می‌تواند حافظه و احساسات را تحریک کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:emotion','emotion','n','احساس','≈ feeling, sentiment — Cambridge 9 · Test 3 · Passage 2: The Psychology of Music | Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At?','Certain melodies evoke strong emotions.','[["Certain melodies evoke strong emotions.","برخی ملودی‌ها احساسات قوی را برمی انگیزند."],["Humour evokes positive emotions.","شوخ طبعی احساسات مثبت را برمی انگیزد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
