INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:therapeutic','therapeutic','adj','درمانی','≈ healing, curative — Cambridge 9 · Test 3 · Passage 2: The Psychology of Music | Cambridge 12 · Test 4 · Passage 2: The Psychology of Music | Cambridge 14 · Test 1 · Passage 1: The Role of Play in Child Development','Music therapy has therapeutic effects on patients.','[["Music therapy has therapeutic effects on patients.","موسیقی درمانی اثرات درمانی بر بیماران دارد."],["Music therapy provides therapeutic benefits for anxiety.","موسیقی درمانی مزایای درمانی برای اضطراب دارد."],["Play has therapeutic effects on traumatized children.","بازی تأثیرات درمانی بر کودکان آسیب دیده دارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
