INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:exploit','exploit','v','بهره‌برداری کردن','≈ utilize, take advantage of — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic','Companies exploit natural resources in polar regions.','[["Companies exploit natural resources in polar regions.","شرکت‌ها از منابع طبیعی در مناطق قطبی بهره برداری می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:controversy','controversy','n','بحث‌برانگیزی','≈ dispute, debate — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic','Oil drilling in the Arctic causes international controversy.','[["Oil drilling in the Arctic causes international controversy.","حفاری نفت در قطب شمال جنجال بین المللی را به همراه دارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:resource','resource','n','منبع','≈ supply, asset — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic','Arctic resources include oil, gas, and minerals.','[["Arctic resources include oil, gas, and minerals.","منابع قطب شمال شامل نفت، گاز و مواد معدنی است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:ecosystem','ecosystem','n','زیست‌بوم','≈ environment, habitat — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic | Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration | Cambridge 14 · Test 3 · Passage 2: Forest Ecosystems and Carbon Balance','Melting ice threatens the entire Arctic ecosystem.','[["Melting ice threatens the entire Arctic ecosystem.","ذوب شدن یخ‌ها کل اکوسیستم قطب شمال را تهدید می‌کند."],["Pollution threatens fragile marine ecosystems.","آلودگی اکوسیستم‌های شکننده دریایی را تهدید می‌کند."],["Healthy ecosystems support biodiversity.","اکوسیستم‌های سالم از تنوع زیستی حمایت می‌کنند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:biodiversity','biodiversity','n','تنوع زیستی','≈ variety of species — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic | Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration | Cambridge 14 · Test 3 · Passage 2: Forest Ecosystems and Carbon Balance','Climate change endangers biodiversity.','[["Climate change endangers biodiversity.","تغییرات آب و هوایی تنوع زیستی را به خطر می‌اندازد."],["Coral reefs are hotspots of marine biodiversity.","صخره‌های مرجانی نقاط داغ تنوع زیستی دریایی هستند."],["Logging reduces global biodiversity levels.","قطع درختان سطح تنوع زیستی جهانی را کاهش می‌دهد."],["Protecting bees helps maintain biodiversity.","حفاظت از زنبورها به حفظ تنوع زیستی کمک می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:sovereignty','sovereignty','n','حاکمیت، مالکیت ملی','≈ authority, control — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic','Nations dispute sovereignty over Arctic waters.','[["Nations dispute sovereignty over Arctic waters.","کشورها بر حق حاکمیت بر آب‌های قطب شمال مناقشه دارند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:diplomatic','diplomatic','adj','دیپلماتیک، وابسته به روابط بین‌الملل','≈ political, tactful — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic','Diplomatic negotiations are needed to resolve Arctic claims.','[["Diplomatic negotiations are needed to resolve Arctic claims.","برای حل و فصل ادعاهای قطب شمال به مذاکرات دیپلماتیک نیاز است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:sustainable','sustainable','adj','پایدار','≈ eco-friendly, renewable — Cambridge 9 · Test 3 · Passage 3: The Future of the Arctic | Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design | Cambridge 14 · Test 2 · Passage 1: Environmental Architecture','The Arctic needs sustainable policies to prevent overexploitation.','[["The Arctic needs sustainable policies to prevent overexploitation.","قطب شمال به سیاست‌های پایدار برای جلوگیری از بهره برداری بیش از حد نیاز دارد."],["Sustainable design reduces environmental impact.","طراحی پایدار اثرات زیست محیطی را کاهش می‌دهد."],["Sustainable architecture reduces energy waste.","معماری پایدار اتلاف انرژی را کاهش می‌دهد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:inventor','inventor','n','مخترع','≈ creator, originator — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell','Alexander Graham Bell was the inventor of the telephone.','[["Alexander Graham Bell was the inventor of the telephone.","الکساندر گراهام بل مخترع تلفن بود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:experimentation','experimentation','n','آزمایشگری','≈ testing, trial — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell | Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education | Cambridge 16 · Test 2 · Passage 2: Animal Intelligence','Years of experimentation led to the invention of the telephone.','[["Years of experimentation led to the invention of the telephone.","سالها آزمایش منجر به اختراع تلفن شد."],["Creativity flourishes through experimentation.","خلاقیت از طریق آزمایش شکوفا می‌شود."],["Controlled experimentation measures learning ability.","آزمایش کنترل شده توانایی یادگیری را اندازه گیری می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:demonstrate','demonstrate','v','نمایش دادن، نشان دادن','≈ show, prove — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell','He demonstrated his device to investors in Boston.','[["He demonstrated his device to investors in Boston.","او دستگاه خود را به سرمایه گذاران در بوستون نشان داد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:acoustic','acoustic','adj','مرتبط با صدا','≈ auditory, sonic — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell | Cambridge 11 · Test 2 · Passage 3: Animal Communication & Language Evolution | Cambridge 14 · Test 4 · Passage 3: Animal Communication','Bell studied acoustic science to improve transmission.','[["Bell studied acoustic science to improve transmission.","بل علم آکوستیک را برای بهبود انتقال مطالعه کرد."],["Acoustic signals travel farther in open environments.","سیگنال‌های صوتی در محیط‌های باز دورتر حرکت می‌کنند."],["Acoustic communication helps detect mates or predators.","ارتباط صوتی به شناسایی جفت یا شکارچیان کمک می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:prototype','prototype','n','نمونه ی اولیه','≈ model, test version — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell | Cambridge 10 · Test 2 · Passage 2: The Construction of the Sydney Opera House | Cambridge 13 · Test 4 · Passage 2: Architectural Innovation & Design Philosophy','The prototype was crude but functional.','[["The prototype was crude but functional.","نمونه اولیه خام اما کاربردی بود."],["Engineers built a prototype of the roof for testing.","مهندسان یک نمونه اولیه از سقف را برای آزمایش ساختند."],["The prototype was tested before mass production.","نمونه اولیه قبل از تولید انبوه آزمایش شد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:collaboration','collaboration','n','همکاری','≈ cooperation, teamwork — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell | Cambridge 10 · Test 3 · Passage 3: Teamwork and Collaboration','Collaboration with technicians helped finalize the invention.','[["Collaboration with technicians helped finalize the invention.","همکاری با تکنسین‌ها به نهایی شدن اختراع کمک کرد."],["Collaboration increases productivity in complex projects.","همکاری باعث افزایش بهره وری در پروژه‌های پیچیده می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:demonstration','demonstration','n','نمایش عملی','≈ presentation, display — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell','The public demonstration attracted widespread attention.','[["The public demonstration attracted widespread attention.","تظاهرات عمومی توجه گسترده ای را به خود جلب کرد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:recognition','recognition','n','شناخت، به‌رسمیت شناسی','≈ acknowledgement, credit — Cambridge 9 · Test 4 · Passage 1: The Life of Alexander Graham Bell | Cambridge 13 · Test 1 · Passage 3: The Art of Photography | Cambridge 14 · Test 1 · Passage 3: Workplace Motivation & Productivity','He gained international recognition for his work.','[["He gained international recognition for his work.","او به خاطر کارش شهرت بین المللی به دست آورد."],["The artist gained recognition posthumously.","این هنرمند پس از مرگ به رسمیت شناخته شد."],["Recognition raises employee morale.","شناخت روحیه کارکنان را بالا می‌برد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:lightning','lightning','n','رعد و برق','≈ electrical discharge — Cambridge 9 · Test 4 · Passage 2: Striking Back at Lightning with Lasers','Lightning can strike tall buildings during storms.','[["Lightning can strike tall buildings during storms.","رعد و برق می‌تواند در هنگام طوفان به ساختمان‌های بلند برخورد کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:conductive','conductive','adj','رسانا','≈ transmissive, electric — Cambridge 9 · Test 4 · Passage 2: Striking Back at Lightning with Lasers','Metal objects are highly conductive to electricity.','[["Metal objects are highly conductive to electricity.","اجسام فلزی به شدت رسانای الکتریسیته هستند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
