INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:trigger','trigger','v','باعث شدن، تحریک کردن','≈ cause, initiate — Cambridge 9 · Test 4 · Passage 2: Striking Back at Lightning with Lasers | Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At?','Lasers can trigger controlled lightning strikes.','[["Lasers can trigger controlled lightning strikes.","لیزرها می‌توانند رعد و برق‌های کنترل شده را تحریک کنند."],["Funny situations trigger laughter.","موقعیت‌های خنده دار باعث خنده می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
