INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:phenomenon','phenomenon','n','پدیده','≈ event, occurrence — Cambridge 9 · Test 4 · Passage 2: Striking Back at Lightning with Lasers | Cambridge 11 · Test 3 · Passage 2: Einstein''s Theory of Relativity','Lightning is a natural atmospheric phenomenon.','[["Lightning is a natural atmospheric phenomenon.","رعد و برق یک پدیده طبیعی جوی است."],["Relativity explains astronomical phenomena like black holes.","نسبیت پدیده‌های نجومی مانند سیاهچاله‌ها را توضیح می‌دهد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
