INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:evolutionary','evolutionary','adj','تکاملی','≈ adaptive, biological — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At? | Cambridge 11 · Test 2 · Passage 3: Animal Communication & Language Evolution','Humour may have an evolutionary function in bonding.','[["Humour may have an evolutionary function in bonding.","طنز ممکن است یک عملکرد تکاملی در پیوند داشته باشد."],["Language evolution reflects social cooperation.","تکامل زبان نشان دهنده همکاری اجتماعی است."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:bond','bond','n','رابطه، پیوند','≈ connection, link — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At?','Laughter creates a social bond between people.','[["Laughter creates a social bond between people.","خنده باعث ایجاد پیوند اجتماعی بین افراد می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:relieve','relieve','v','کاهش دادن استرس، تسکین دادن','≈ ease, alleviate — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At?','Laughter helps relieve stress and anxiety.','[["Laughter helps relieve stress and anxiety.","خنده به کاهش استرس و اضطراب کمک می‌کند."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:mechanism','mechanism','n','سازوکار','≈ process, system — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At? | Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping','Scientists study the mechanism of humour response in the brain.','[["Scientists study the mechanism of humour response in the brain.","دانشمندان مکانیسم واکنش شوخ طبعی را در مغز مطالعه می‌کنند."],["The clock''s mechanism was remarkably precise.","مکانیسم ساعت بسیار دقیق بود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:experiment','experiment','n','آزمایش','≈ test, trial — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At?','Experiments show that shared laughter builds trust.','[["Experiments show that shared laughter builds trust.","آزمایش‌ها نشان می‌دهد که خنده مشترک باعث ایجاد اعتماد می‌شود."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:correlation','correlation','n','رابطه، همبستگی','≈ connection, association — Cambridge 9 · Test 4 · Passage 3: What Are You Laughing At? | Cambridge 11 · Test 1 · Passage 3: Neuroeconomics | Cambridge 15 · Test 3 · Passage 3: Climate Records & Historical Change (Geology & Environmental','There is a strong correlation between laughter and group cohesion.','[["There is a strong correlation between laughter and group cohesion.","بین خنده و انسجام گروهی همبستگی قوی وجود دارد."],["There''s a correlation between stress and poor judgment.","بین استرس و قضاوت ضعیف همبستگی وجود دارد."],["There is a strong correlation between CO₂ and temperature.","همبستگی قوی بین CO2 و دما وجود دارد."]]','cambridge',1,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:chronology','chronology','n','ترتیب زمانی رویدادها','≈ timeline, sequence — Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping | Cambridge 16 · Test 3 · Passage 2: Archaeological Discovery','The book presents events in strict chronology.','[["The book presents events in strict chronology.","این کتاب رویدادها را در زمان بندی دقیق ارائه می‌کند."],["Researchers established a clear chronology of events.","محققان یک گاهشماری روشن از رویدادها ایجاد کردند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:sundial','sundial','n','ساعت آفتابی','≈ solar clock — Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping','Ancient civilizations used sundials to measure daylight hours.','[["Ancient civilizations used sundials to measure daylight hours.","تمدن‌های باستان از ساعت‌های آفتابی برای اندازه گیری ساعات روز استفاده می‌کردند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
