INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:pendulum','pendulum','n','آونگ','≈ swinging weight — Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping','The pendulum regulates the clock''s accuracy.','[["The pendulum regulates the clock''s accuracy.","آونگ دقت ساعت را تنظیم می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:longitude','longitude','n','طول جغرافیایی','≈ geographic coordinate — Cambridge 10 · Test 1 · Passage 1: The History of Timekeeping | Cambridge 12 · Test 3 · Passage 2: The History of Cartography | Cambridge 13 · Test 3 · Passage 2: Arctic Tern Migration','Sailors needed longitude to navigate accurately.','[["Sailors needed longitude to navigate accurately.","ملوانان برای ناوبری دقیق به طول جغرافیایی نیاز داشتند."],["Longitude helps determine precise locations.","طول جغرافیایی به تعیین مکان‌های دقیق کمک می‌کند."],["They follow a consistent longitude each season.","آنها در هر فصل یک طول جغرافیایی ثابت را دنبال می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
