INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:ritual','ritual','n','آیین، مراسم سنتی','≈ ceremony, tradition — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture | Cambridge 15 · Test 3 · Passage 1: Ancient Cave Paintings & Human Expression','Music and dance were part of sacred rituals.','[["Music and dance were part of sacred rituals.","موسیقی و رقص بخشی از آیین‌های مقدس بود."],["Rituals were central to prehistoric spiritual life.","تشریفات در زندگی معنوی ماقبل تاریخ نقش اساسی داشتند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:oral tradition','oral tradition','n','سنت گفتاری / نقل شفاهی','≈ spoken heritage — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture | Cambridge 19 · Test 4 · Passage 1: Anthropology & Cultural Development','Knowledge was passed down through oral tradition.','[["Knowledge was passed down through oral tradition.","دانش از طریق سنت شفاهی منتقل شد."],["Oral traditions transmitted myths and values.","سنت‌های شفاهی اسطوره‌ها و ارزش‌ها را منتقل می‌کردند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:spiritual','spiritual','adj','روحانی، معنوی','≈ sacred, religious — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture','The rock paintings have spiritual meanings.','[["The rock paintings have spiritual meanings.","نقاشی‌های صخره ای معانی معنوی دارند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:indigenous','indigenous','adj','بومی','≈ native, local — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture','Indigenous Australians have lived there for over 40,000 years.','[["Indigenous Australians have lived there for over 40,000 years.","بومیان استرالیا بیش از 40000 سال است که در آنجا زندگی می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:landscape','landscape','n','منظره طبیعی','≈ scenery, terrain — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture','The landscape reflects their connection to nature.','[["The landscape reflects their connection to nature.","منظره نشان دهنده ارتباط آنها با طبیعت است."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:preservation','preservation','n','حفظ و نگهداری','≈ protection, conservation — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture | Cambridge 10 · Test 4 · Passage 2: The Lost Civilisations of South America | Cambridge 13 · Test 1 · Passage 1: Tourism & Global Development','Preservation of rock art is a cultural priority.','[["Preservation of rock art is a cultural priority.","حفظ هنر صخره ای یک اولویت فرهنگی است."],["Preservation of ancient ruins is crucial.","حفظ ویرانه‌های باستانی بسیار مهم است."],["Preservation of monuments prevents damage.","حفظ آثار از آسیب جلوگیری می‌کند."],["Preservation efforts prevent cave art deterioration.","تلاش‌های حفاظتی از زوال هنر غار جلوگیری می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:custodian','custodian','n','نگهبان فرهنگی / متولی','≈ guardian, caretaker — Cambridge 10 · Test 1 · Passage 2: The Architecture of Aboriginal Culture','Elders act as custodians of tribal knowledge.','[["Elders act as custodians of tribal knowledge.","بزرگان به عنوان نگهبان دانش قبیله ای عمل می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
